function systemLang() {
  const list = (navigator.languages && navigator.languages.length)
    ? navigator.languages
    : [navigator.language || "en"];
  for (const raw of list) {
    const l = String(raw).toLowerCase();
    if (l.startsWith("uk")) return "uk";
    if (l.startsWith("pl")) return "pl";
    if (l.startsWith("en")) return "en";
  }
  return "en";
}
const state = JSON.parse(localStorage.getItem("talerz") || "null") || {
  lang: systemLang(),
  langChosen: false,
  user: null,
  meals: [],
  workouts: [],
  screen: "login",
};
if (!state.langChosen) state.lang = systemLang();
if (state.model !== "flash" && state.model !== "lite") state.model = "lite";
if (localStorage.getItem("mealquo_clean") !== "4") {
  state.meals = [];
  state.workouts = [];
  if (state.screen === "onboard") state.screen = state.user ? "home" : "login";
  localStorage.setItem("mealquo_clean", "4");
}
if (!state.dateFix) {
  fixDates(state);
  state.rev = Date.now();
  store("talerz", JSON.stringify(state));
}
// do 14.6 zdjęcia posiłków siedziały w localStorage (dwie kopie), które mieści ~18 zdjęć
if (movePhotos(state)) {
  state.rev = Date.now();
  store("talerz", JSON.stringify(state));
}
moveBookPhotos();
// na iPhonie (web.js) mostek powstaje po app.js, więc przenosiny jeszcze raz po starcie
setTimeout(() => {
  if (movePhotos(state)) { state.rev = Date.now(); store("talerz", JSON.stringify(state)); }
  moveBookPhotos();
  prunePhotos();
}, 8000);

// localStorage.setItem bez wyjątku przy przepełnieniu
function store(key, value) {
  try { localStorage.setItem(key, value); return true; } catch (_) { return false; }
}
// zdjęcie posiłku do pliku w aplikacji; zwraca file://, a bez Androida zostawia data:
function storePhoto(url) {
  if (!url || String(url).indexOf("data:") !== 0) return url || null;
  if (!(window.MealquoNative && MealquoNative.savePhoto)) return url;
  try { return MealquoNative.savePhoto(url) || url; } catch (_) { return url; }
}
function movePhotos(src) {
  let moved = false;
  (src && src.meals || []).forEach((m) => {
    if (!m.thumb || String(m.thumb).indexOf("data:") !== 0) return;
    const file = storePhoto(m.thumb);
    if (file !== m.thumb) { m.thumb = file; moved = true; }
  });
  return moved;
}
function bookKeys() {
  const keys = [];
  for (let i = 0; i < localStorage.length; i++) {
    const k = localStorage.key(i);
    if (k && k.indexOf("mealquo_book_") === 0) keys.push(k);
  }
  return keys;
}
function moveBookPhotos() {
  bookKeys().forEach((k) => {
    try {
      const book = JSON.parse(localStorage.getItem(k) || "null");
      if (book && movePhotos(book)) store(k, JSON.stringify(book));
    } catch (_) {}
  });
}
// usuwa pliki zdjęć, których nie ma już w żadnym dzienniku (także innych kont)
function prunePhotos() {
  if (!(window.MealquoNative && MealquoNative.prunePhotos)) return;
  const keep = new Set();
  const add = (src) => (src && src.meals || []).forEach((m) => {
    const t = String(m.thumb || "");
    if (t.indexOf("file:") === 0 || t.indexOf("photos/") === 0) keep.add(t.split("/").pop());
  });
  add(state);
  bookKeys().forEach((k) => { try { add(JSON.parse(localStorage.getItem(k) || "null")); } catch (_) {} });
  MealquoNative.prunePhotos(JSON.stringify([...keep]));
}
// ostatnia deska ratunku przy pełnym localStorage: zdjęcia do plików, a bez Androida bez zdjęć w starszych posiłkach
function freeSpace() {
  movePhotos(state);
  const meals = (state.meals || []).slice().sort((a, b) => (+a.id || 0) - (+b.id || 0));
  meals.slice(0, Math.max(0, meals.length - 6)).forEach((m) => {
    if (m.thumb && String(m.thumb).indexOf("data:") === 0) m.thumb = null;
  });
}
function toast(text, ms) {
  const pop = document.createElement("div");
  pop.className = "saved-pop";
  pop.textContent = text;
  document.body.appendChild(pop);
  setTimeout(() => pop.remove(), ms || 1400);
}
// błędy JS do dziennika w aplikacji (raport z profilu)
function logError(text) {
  try { if (window.MealquoNative && MealquoNative.logError) MealquoNative.logError(String(text).slice(0, 2000)); } catch (_) {}
}
window.addEventListener("error", (e) => logError((e.message || "error") + " @" + (e.lineno || 0) + ":" + (e.colno || 0) + " " + (e.error && e.error.stack || "")));
window.addEventListener("unhandledrejection", (e) => logError("promise " + (e.reason && (e.reason.stack || e.reason.message) || e.reason)));
let aiErrorAt = 0;
window.onAiError = (kind) => {
  if (Date.now() - aiErrorAt < 8000) return;
  aiErrorAt = Date.now();
  const text = {
    offline: L("Brak internetu. Sprawdź połączenie i spróbuj ponownie.", "Немає інтернету. Перевір з’єднання і спробуй ще.", "No internet. Check your connection and try again."),
    timeout: L("AI odpowiada za wolno. Spróbuj za chwilę.", "AI відповідає надто повільно. Спробуй за хвилину.", "The AI is too slow right now. Try again in a moment."),
    busy: L("Za dużo zapytań naraz. Spróbuj za minutę.", "Забагато запитів одразу. Спробуй за хвилину.", "Too many requests at once. Try again in a minute."),
    quota: L("Dzisiejszy limit AI się wyczerpał. Spróbuj później.", "Денний ліміт AI вичерпано. Спробуй пізніше.", "Today's AI limit is used up. Try again later."),
    key: L("AI jest niedostępne w tej wersji aplikacji. Zaktualizuj Mealquo.", "AI недоступний у цій версії. Онови Mealquo.", "The AI is unavailable in this version. Update Mealquo."),
    server: L("Serwer AI ma problem. Spróbuj za chwilę.", "Сервер AI має проблему. Спробуй за хвилину.", "The AI server has a problem. Try again in a moment."),
  }[kind];
  if (text) toast(text, 3500);
};

function iso(d) {
  const x = new Date(d);
  return x.getFullYear() + "-" + String(x.getMonth() + 1).padStart(2, "0") + "-" + String(x.getDate()).padStart(2, "0");
}
// do 14.5 iso() liczyło datę w UTC, więc na wschód od UTC zapisywało dzień wcześniej; przesuwa stare daty o +1
function fixDates(src) {
  if (!src || src.dateFix) return;
  if (new Date().getTimezoneOffset() < 0) {
    const next = (d) => {
      if (!/^\d{4}-\d{2}-\d{2}$/.test(d || "")) return d;
      const x = new Date(d + "T12:00:00");
      x.setDate(x.getDate() + 1);
      return iso(x);
    };
    (src.meals || []).forEach((m) => { m.date = next(m.date); });
    (src.workouts || []).forEach((w) => { if (!w.watchId) w.date = next(w.date); });
    ["plans", "night", "ask"].forEach((k) => { if (src[k] && src[k].day) src[k].day = next(src[k].day); });
  }
  src.dateFix = 1;
}
let lastSaved = "";
let spaceWarned = false;
function save() {
  mealIndex = null;
  // render() woła save() przy każdym rysowaniu; bez zmian nie zapisujemy ani nie synchronizujemy
  const now = JSON.stringify({ ...state, rev: 0 });
  if (now === lastSaved) return;
  lastSaved = now;
  if (!applyingRemote && syncReady) state.rev = Date.now();
  if (!store("talerz", JSON.stringify(state))) {
    freeSpace();
    if (!store("talerz", JSON.stringify(state)) && !spaceWarned) {
      spaceWarned = true;
      toast(L("Pamięć aplikacji jest pełna, ostatnie zmiany mogą się nie zapisać.", "Пам’ять застосунку заповнена, останні зміни можуть не зберегтися.", "App storage is full, recent changes may not be saved."), 4000);
    }
  }
  writeBook();
  if (!applyingRemote && syncReady) {
    schedulePush();
    scheduleCloud();
  }
}
let applyingRemote = false;
let syncReady = false;
let pushTimer = 0;
let cloudTimer = 0;
function bookId(email) { return "mealquo_book_" + String(email || "").toLowerCase(); }
function readBook(email) {
  try { return JSON.parse(localStorage.getItem(bookId(email)) || "null"); }
  catch { return null; }
}
function writeBook() {
  const email = state.user && state.user.email;
  if (!email) return null;
  const book = {
    rev: state.rev || Date.now(),
    dateFix: 1,
    meals: state.meals || [],
    workouts: state.workouts || [],
    deleted: state.deleted || [],
    likes: state.likes || {},
    pairs: state.pairs || [],
    points: state.points || 0,
    round: state.round || 1,
    seenIdeas: state.seenIdeas || [],
    pending: state.pending || [],
    settings: state.settings,
    taste: state.taste,
    plans: state.plans,
    user: state.user,
    weights: state.weights || [],
    quests: state.quests,
    badges: state.badges,
    game: state.game,
    coach: state.coach,
    goalStart: state.goalStart,
    steps: state.steps,
  };
  store(bookId(email), JSON.stringify(book));
  return book;
}
function emptyDiary() {
  state.meals = [];
  state.workouts = [];
  state.deleted = [];
  state.likes = {};
  state.pairs = [];
  state.points = 0;
  state.round = 1;
  state.seenIdeas = [];
  state.pending = [];
  state.plans = null;
  state.taste = {};
  state.weights = [];
  state.quests = null;
  state.badges = null;
  state.game = null;
  state.coach = null;
  state.goalStart = null;
  state.consent = null;
  state.steps = null;
}
function applyBook(book) {
  if (!book) return;
  fixDates(book);
  const email = (state.user && state.user.email) || (book.user && book.user.email);
  if (Array.isArray(book.meals)) state.meals = book.meals;
  if (Array.isArray(book.workouts)) state.workouts = book.workouts;
  if (Array.isArray(book.deleted)) state.deleted = book.deleted;
  if (book.likes) state.likes = book.likes;
  if (Array.isArray(book.pairs)) state.pairs = book.pairs;
  if (book.points != null) state.points = book.points;
  if (book.round != null) state.round = book.round;
  if (Array.isArray(book.seenIdeas)) state.seenIdeas = book.seenIdeas;
  if (Array.isArray(book.pending)) state.pending = book.pending;
  if (book.settings) state.settings = book.settings;
  if (book.taste) state.taste = book.taste;
  if (book.plans) state.plans = book.plans;
  if (Array.isArray(book.weights)) state.weights = book.weights;
  if (book.quests) state.quests = book.quests;
  if (book.badges) state.badges = book.badges;
  if (book.game) state.game = book.game;
  if (book.coach) state.coach = book.coach;
  if (book.goalStart) state.goalStart = book.goalStart;
  if (book.steps) state.steps = book.steps;
  if (book.user) state.user = Object.assign({}, book.user, { email });
  if (book.rev) state.rev = book.rev;
}
function cloudOk() { return location.protocol === "http:" || location.protocol === "https:"; }
// baza Mealquo: iPhone przez fetch (/api/journal), Android przez mostek (MealquoNative.cloudJournal)
function cloudSync() { return cloudOk() || !!(window.MealquoNative && MealquoNative.cloudJournal); }
const cloudWaits = {};
let cloudSeq = 0;
function cloudJournal(payload) {
  return cloudApi("/api/journal", payload);
}
// zapytanie do serwera Mealquo: iPhone fetch, Android mostek (token aplikacji dokłada Java)
function cloudApi(path, payload, token) {
  if (window.MealquoNative && MealquoNative.cloudApi) {
    return new Promise((resolve) => {
      const id = "cj" + (++cloudSeq);
      cloudWaits[id] = resolve;
      MealquoNative.cloudApi(id, path, JSON.stringify(payload), token || "");
      setTimeout(() => { if (cloudWaits[id]) { delete cloudWaits[id]; resolve({ status: 0, data: {} }); } }, 30000);
    });
  }
  if (window.MealquoNative && MealquoNative.cloudJournal && path === "/api/journal") {
    return new Promise((resolve) => {
      const id = "cj" + (++cloudSeq);
      cloudWaits[id] = resolve;
      MealquoNative.cloudJournal(id, JSON.stringify(payload));
      setTimeout(() => { if (cloudWaits[id]) { delete cloudWaits[id]; resolve({ status: 0, data: {} }); } }, 30000);
    });
  }
  if (!cloudOk()) return Promise.resolve({ status: 0, data: {} });
  const headers = { "Content-Type": "application/json" };
  if (token) headers.Authorization = "Bearer " + token;
  return fetch(path, { method: "POST", headers, body: JSON.stringify(payload) })
    .then(async (res) => ({ status: res.status, data: await res.json().catch(() => ({})) }))
    .catch(() => ({ status: 0, data: {} }));
}

// --- konto na serwerze i synchronizacja wpisów (API v2: posiłki, treningi, ustawienia osobno) ---
// cele i gra (weights, quests, badges, game, coach, goalStart) też wędrują między telefonami konta
const SYNC_DOCS = ["likes", "pairs", "points", "round", "seenIdeas", "pending", "settings", "taste", "plans", "user", "weights", "quests", "badges", "game", "coach", "goalStart", "steps"];
function v2Key(email) { return "mealquo_v2_" + String(email || "").toLowerCase(); }
function v2Session(email) {
  try { return JSON.parse(localStorage.getItem(v2Key(email)) || "null"); } catch (_) { return null; }
}
function v2Store(email, sess) { store(v2Key(email), JSON.stringify(sess)); }
function v2Drop(email) { try { localStorage.removeItem(v2Key(email)); } catch (_) {} }
function v2Device() { return (window.MealquoNative && MealquoNative.cloudApi ? "android " : "web ") + (window.MealquoNative?.appVersion?.() || ""); }
// zdjęcia zostają w telefonie (adres pliku nic nie znaczy na innym urządzeniu)
function syncData(kind, obj) {
  if (kind === "doc") return obj;
  const copy = Object.assign({}, obj);
  delete copy.thumb; delete copy.thumbs;
  if (copy.photo && String(copy.photo).indexOf("http") !== 0) delete copy.photo;
  return copy;
}
function syncHash(data) {
  const text = JSON.stringify(data) || "";
  let h = 2166136261;
  for (let i = 0; i < text.length; i++) { h ^= text.charCodeAt(i); h = Math.imul(h, 16777619); }
  return (h >>> 0).toString(36) + text.length.toString(36);
}
function localEntries() {
  const out = new Map();
  const gone = new Set((state.deleted || []).map(String));
  for (const m of state.meals || []) if (m && m.id != null && !gone.has(String(m.id))) out.set("meal:" + m.id, { kind: "meal", id: String(m.id), data: syncData("meal", m) });
  for (const w of state.workouts || []) if (w && w.id != null) out.set("workout:" + w.id, { kind: "workout", id: String(w.id), data: syncData("workout", w) });
  for (const k of SYNC_DOCS) if (state[k] !== undefined && state[k] !== null) out.set("doc:" + k, { kind: "doc", id: k, data: state[k] });
  return out;
}
// wpis z serwera do stanu; zwraca dane po scaleniu (do skrótu)
function applyEntry(c) {
  if (c.kind === "doc") {
    if (!SYNC_DOCS.includes(c.id)) return null;
    if (c.id === "user" && c.data && state.user) c.data = Object.assign({}, c.data, { email: state.user.email });
    state[c.id] = c.data;
    return c.data;
  }
  const list = c.kind === "meal" ? (state.meals ||= []) : (state.workouts ||= []);
  const at = list.findIndex((x) => String(x.id) === c.id);
  if (c.deleted) {
    if (at >= 0) list.splice(at, 1);
    return null;
  }
  const merged = Object.assign({}, c.data);
  if (at >= 0 && list[at].thumb) merged.thumb = list[at].thumb;
  if (at >= 0) list[at] = merged; else list.push(merged);
  if (c.kind === "meal") state.deleted = (state.deleted || []).filter((d) => String(d) !== c.id);
  return syncData(c.kind, merged);
}
let v2Busy = false;
let v2Again = false;
// true = konto jest na serwerze v2 (zsynchronizowane albo spróbuje później)
async function syncV2() {
  const email = state.user && state.user.email;
  const sess = email && v2Session(email);
  if (!sess || !sess.token) return false;
  if (v2Busy) { v2Again = true; return true; }
  v2Busy = true;
  try {
    const synced = sess.synced || {};
    let changes = [];
    // pierwsze połączenie urządzenia: najpierw stan z serwera (wygrywa), potem wysyłka tego, czego tam nie ma
    if (sess.cursor) {
      const now = Date.now();
      const local = localEntries();
      for (const [key, e] of local) {
        const h = syncHash(e.data);
        if (synced[key] !== h) changes.push({ kind: e.kind, id: e.id, data: e.data, updated_at: now, _h: h });
      }
      for (const key of Object.keys(synced)) {
        if (local.has(key)) continue;
        const [kind, ...rest] = key.split(":");
        changes.push({ kind, id: rest.join(":"), deleted: true, updated_at: now });
      }
    }
    for (let round = 0; round < 50; round++) {
      const batch = changes.slice(0, 400);
      changes = changes.slice(400);
      const r = await cloudApi("/api/v2/sync", { since: sess.cursor || 0, changes: batch.map(({ _h, ...c }) => c) }, sess.token);
      if (r.status === 401) { v2Drop(email); return false; }
      if (r.status !== 200) return true;
      for (const c of batch) {
        const key = c.kind + ":" + c.id;
        if (c.deleted) delete synced[key]; else synced[key] = c._h;
      }
      let touched = false;
      applyingRemote = true;
      for (const c of r.data.changes || []) {
        const key = c.kind + ":" + c.id;
        if (c.deleted) {
          if (synced[key] !== undefined || (c.kind !== "doc")) { applyEntry(c); touched = true; }
          delete synced[key];
          continue;
        }
        if (synced[key] === syncHash(c.data)) continue;   // nasza własna zmiana
        const merged = applyEntry(c);
        if (merged !== null) { synced[key] = syncHash(merged); touched = true; }
      }
      applyingRemote = false;
      const first = !sess.cursor;
      sess.cursor = r.data.cursor || sess.cursor || 1;
      sess.synced = synced;
      v2Store(email, sess);
      if (touched) {
        applyingRemote = true;
        save();
        applyingRemote = false;
        render();
      }
      // po pierwszym pobraniu: wysyłka lokalnych wpisów, których serwer nie ma
      if (first) {
        const local = localEntries();
        const now = Date.now();
        for (const [key, e] of local) {
          const h = syncHash(e.data);
          if (synced[key] !== h && synced[key] === undefined) changes.push({ kind: e.kind, id: e.id, data: e.data, updated_at: now, _h: h });
        }
      }
      if (!changes.length) break;
    }
    await syncPhotos(sess);
    return true;
  } finally {
    applyingRemote = false;
    v2Busy = false;
    if (v2Again) { v2Again = false; scheduleCloud(); }
  }
}
// --- zdjęcia posiłków na serwerze: widoczne na każdym telefonie konta ---
function photoList(name) {
  try { return JSON.parse(localStorage.getItem(name) || "[]"); } catch (_) { return []; }
}
function photoListSave(name, list) { store(name, JSON.stringify(list.slice(-300))); }
function queuePhoto(id) { if (id) photoListSave("mealquo_photo_up", [...new Set([...photoList("mealquo_photo_up"), id])]); }
// base64 zdjęcia z telefonu (file:// na Androidzie, photos/… w wersji na iPhone'a, data:)
async function photoData(thumb) {
  const t = String(thumb || "");
  if (t.indexOf("data:") === 0) return t.split(",")[1] || "";
  if (window.MealquoNative && MealquoNative.photoB64) {
    try { return (await Promise.resolve(MealquoNative.photoB64(t))) || ""; } catch (_) { return ""; }
  }
  return "";
}
async function syncPhotos(sess) {
  let assigned = false;
  // posiłki ze zdjęciem sprzed tej wersji: dostają photoId i idą do wysyłki
  for (const m of state.meals || []) {
    if (m.thumb && !m.photoId) { m.photoId = "m" + m.id; queuePhoto(m.photoId); assigned = true; }
  }
  const left = [];
  let sent = 0;
  for (const id of photoList("mealquo_photo_up")) {
    const meal = (state.meals || []).find((m) => m.photoId === id);
    if (!meal || !meal.thumb) continue;
    if (sent >= 10) { left.push(id); continue; }
    sent++;
    const data = await photoData(meal.thumb);
    if (!data) continue;
    const r = await cloudApi("/api/v2/photo/put", { id, data }, sess.token);
    if (r.status !== 200 && r.status !== 400 && r.status !== 413) left.push(id);
  }
  photoListSave("mealquo_photo_up", left);
  // posiłki z innego telefonu: zdjęcie z serwera do pamięci tego telefonu
  const misses = (() => { try { return JSON.parse(localStorage.getItem("mealquo_photo_miss") || "{}"); } catch (_) { return {}; } })();
  let got = 0;
  for (const m of state.meals || []) {
    if (got >= 10 || !m.photoId || m.thumb || (misses[m.photoId] || 0) >= 5) continue;
    got++;
    const r = await cloudApi("/api/v2/photo/get", { id: m.photoId }, sess.token);
    const file = r.status === 200 && r.data.data ? storePhoto("data:image/jpeg;base64," + r.data.data) : null;
    if (file) { m.thumb = file; delete misses[m.photoId]; } else misses[m.photoId] = (misses[m.photoId] || 0) + 1;
  }
  store("mealquo_photo_miss", JSON.stringify(misses));
  if (assigned) save();                   // photoId idzie na serwer zwykłą synchronizacją
  else if (got) { applyingRemote = true; save(); applyingRemote = false; }
  if (got) render();
}
// telefon zalogowany przed v2: konto przechodzi na serwer skrótem hasła, bez pytania o hasło
async function v2Upgrade() {
  const email = state.user && state.user.email;
  const acc = email && accounts().find((a) => a.email === email);
  if (!acc || !acc.hash || v2Session(email) || !cloudSync()) return false;
  const r = await cloudApi("/api/v2/login", { email, legacy: acc.hash, device: v2Device() });
  if (r.status !== 200 || !r.data.token) return false;
  v2Store(email, { token: r.data.token, cursor: 0, synced: {} });
  return true;
}
window.onCloudJournal = (id, status, packed) => {
  const done = cloudWaits[id];
  if (!done) return;
  delete cloudWaits[id];
  let data = {};
  try { data = JSON.parse(decodeURIComponent(escape(atob(packed)))); } catch (_) {}
  done({ status, data });
};
function scheduleCloud() {
  if (!cloudSync()) return;
  clearTimeout(cloudTimer);
  cloudTimer = setTimeout(pushCloud, 700);
}
// trwa pobieranie dziennika z serwera: wysyłka czeka, żeby pusty stan nie nadpisał kopii
let pulling = false;
async function pushCloud() {
  if (pulling) { scheduleCloud(); return; }
  if (await syncV2()) return;
  const email = state.user && state.user.email;
  const acc = email && accounts().find((a) => a.email === email);
  if (!acc || !acc.hash || !cloudSync()) return;
  const book = writeBook();
  if (!book) return;
  const slim = Object.assign({}, book, {
    meals: (book.meals || []).map((m) => {
      const copy = Object.assign({}, m);
      if (copy.photo && String(copy.photo).length > 4000) delete copy.photo;
      return copy;
    }),
  });
  await cloudJournal({ action: "push", email, hash: acc.hash, journal: slim });
}
// force: logowanie na nowym telefonie – kopia z serwera wygrywa z pustym stanem
async function pullCloud(force) {
  if (state.user && state.user.email && !v2Session(state.user.email)) await v2Upgrade();
  if (v2Session(state.user && state.user.email)) {
    pulling = true;
    try { await syncV2(); } finally { pulling = false; }
    return;
  }
  const email = state.user && state.user.email;
  const acc = email && accounts().find((a) => a.email === email);
  if (!acc || !acc.hash || !cloudSync()) return;
  pulling = true;
  try {
    const { status, data } = await cloudJournal({ action: "pull", email, hash: acc.hash });
    if (status !== 200) return;
    if (!data.found) { pulling = false; pushCloud(); return; }
    const remote = JSON.parse(data.journal || "{}");
    if (force || (remote.rev || 0) >= (state.rev || 0)) {
      applyingRemote = true;
      applyBook(remote);
      state.screen = "home";
      applyingRemote = false;
      render();
    }
  } catch (_) {
  } finally {
    pulling = false;
  }
}
function journalBlob() {
  return JSON.stringify({ rev: state.rev || 0, state, accounts: accounts() });
}
function schedulePush() {
  clearTimeout(pushTimer);
  pushTimer = setTimeout(() => {
    if (window.MealquoNative && window.MealquoNative.pushJournal) window.MealquoNative.pushJournal(journalBlob());
  }, 900);
}
function streakCount() {
  const logged = new Set((state.meals || []).map((m) => m.date));
  // ratunek serii: dni uratowane liczą się jak zapisane
  ((state.game && state.game.frozen) || []).forEach((d) => logged.add(d));
  const today = new Date();
  const yesterday = new Date();
  yesterday.setDate(today.getDate() - 1);
  let cursor = null;
  if (logged.has(iso(today))) cursor = today;
  else if (logged.has(iso(yesterday))) cursor = yesterday;
  if (!cursor) return 0;
  let n = 0;
  for (let i = 0; i < 400; i++) {
    if (!logged.has(iso(cursor))) break;
    n++;
    cursor = new Date(cursor);
    cursor.setDate(cursor.getDate() - 1);
  }
  return n;
}
function streakBadge() {
  const n = streakCount();
  return n > 0 ? `<div class="streak" title="${attr(L("Seria dni z wpisami", "Серія днів із записами", "Days logged in a row"))}">${icon("flame")}<b>${n}</b></div>` : "";
}
function t(k) { return (T[state.lang] && T[state.lang][k]) || T.pl[k] || k; }
function L(pl, uk, en) {
  if (state.lang === "uk") return uk;
  if (state.lang === "en") return en;
  return pl;
}
function foodName(f) { return (f.name && (f.name[state.lang] || f.name.en || f.name.pl)) || ""; }

// pełne lata z daty urodzenia albo null, gdy daty nie ma
function yearsOld(dob) {
  if (!dob) return null;
  const d = new Date(dob);
  if (Number.isNaN(+d)) return null;
  const n = new Date();
  let a = n.getFullYear() - d.getFullYear();
  const m = n.getMonth() - d.getMonth();
  if (m < 0 || (m === 0 && n.getDate() < d.getDate())) a--;
  return a;
}
function ageFromDob(dob) {
  const a = yearsOld(dob);
  return a == null ? 30 : Math.max(10, Math.min(90, a));
}
// tryb nastolatka: 13–15 lat (poniżej 13 nie da się założyć konta) – bez celu wagi i deficytu, misje o nawykach
function teenAge(dob) {
  const a = yearsOld(dob);
  return a != null && a < 16;
}
function isTeen(u) {
  u = u || state.user;
  return !!(u && teenAge(u.dob));
}
function goalPlan(u) {
  const sex = u.sex === "female" ? "female" : "male";
  const weight = Math.max(35, Math.round(+u.weight || 70));
  const height = Math.max(140, Math.round(+u.height || 170));
  const age = ageFromDob(u.dob);
  const bmr = 10 * weight + 6.25 * height - 5 * age + (sex === "female" ? -161 : 5);
  const mult = { low: 1.2, mid: 1.45, high: 1.7 }[u.activity] || 1.45;
  const maintain = Math.max(1200, Math.round(bmr * mult));
  let target = Math.round(+u.targetWeight || weight);
  let goal = u.goal || "keep";
  if (target <= weight - 1) goal = "lose";
  else if (target >= weight + 1) goal = "gain";
  else goal = "keep";
  if (teenAge(u.dob)) { goal = "keep"; target = weight; }   // nastolatek: zapotrzebowanie bez deficytu i bez wagi docelowej
  const pace = u.pace === "easy" || u.pace === "hard" ? u.pace : "normal";
  const floor = sex === "female" ? 1200 : 1500;
  const perKg = 7700;
  let kcal = maintain;
  let kgWeek = 0;
  let days = 0;
  let slow = false;
  const gap = Math.abs(target - weight);
  if (goal === "lose") {
    const maxDef = Math.max(200, maintain - floor);
    // tempo najwyżej 1% masy ciała na tydzień (przy 60 kg „mocno” to 0,6 kg, nie 0,75)
    const kg = Math.min(pace === "easy" ? 0.25 : pace === "hard" ? 0.75 : 0.5, Math.round(weight * 0.01 * 100) / 100);
    const wanted = Math.round(kg * perKg / 7);
    const def = Math.min(wanted, maxDef);
    slow = def < wanted - 20;
    kcal = maintain - def;
    kgWeek = Math.round((def * 7 / perKg) * 100) / 100;
    days = Math.max(7, Math.round(gap / kgWeek * 7));
  } else if (goal === "gain") {
    const kg = pace === "easy" ? 0.15 : pace === "hard" ? 0.45 : 0.3;
    const surplus = Math.min(500, Math.round(kg * perKg / 7));
    kcal = maintain + surplus;
    kgWeek = Math.round((surplus * 7 / perKg) * 100) / 100;
    days = Math.max(7, Math.round(gap / kgWeek * 7));
  } else {
    target = weight;
  }
  let pPerKg = goal === "lose" ? 2 : goal === "gain" ? 1.8 : 1.6;
  if (u.diet === "highp") pPerKg = Math.max(pPerKg, 2);
  if (u.diet === "vegan") pPerKg = Math.max(1.6, pPerKg - 0.1);
  const p = Math.round(weight * pPerKg);
  let f = Math.round((kcal * 0.28) / 9);
  let c = Math.round((kcal - p * 4 - f * 9) / 4);
  if (u.diet === "dia") {
    c = Math.round((kcal * 0.3) / 4);
    f = Math.max(25, Math.round((kcal - p * 4 - c * 4) / 9));
  }
  if (c < 40) {
    c = 40;
    f = Math.max(25, Math.round((kcal - p * 4 - c * 4) / 9));
  }
  return { kcal, p, c, f, days, kgWeek, goal, target, from: weight, maintain, slow, pace };
}
function calcPlan(u) {
  u.age = ageFromDob(u.dob);
  if (teenAge(u.dob)) return goalPlan(Object.assign({}, u, { targetWeight: 0, goal: "keep" }));
  if (u.targetWeight) return goalPlan(u);
  const s = u.sex === "female" ? -161 : 5;
  const bmr = 10 * u.weight + 6.25 * u.height - 5 * u.age + s;
  const mult = { low: 1.2, mid: 1.45, high: 1.7 }[u.activity] || 1.45;
  let kcal = Math.round(bmr * mult);
  if (u.goal === "lose") kcal = Math.round(kcal * 0.82);
  if (u.goal === "gain") kcal = Math.round(kcal * 1.12);
  let pPerKg = u.diet === "highp" ? 2.0 : 1.6;
  if (u.diet === "vegan") pPerKg = 1.7;
  const p = Math.round(u.weight * pPerKg);
  let f = Math.round((kcal * 0.28) / 9);
  let c = Math.round((kcal - p * 4 - f * 9) / 4);
  if (u.diet === "dia") {
    c = Math.round((kcal * 0.3) / 4);
    f = Math.round((kcal - p * 4 - c * 4) / 9);
  }
  return { kcal, p, c, f };
}

// posiłki pogrupowane po dniu; odbudowywane przy zmianie listy (save() i render() zerują indeks)
let mealIndex = null;
let mealIndexOf = null;
let mealIndexLen = -1;
function dayMeals(day) {
  if (!mealIndex || mealIndexOf !== state.meals || mealIndexLen !== state.meals.length) {
    mealIndex = new Map();
    for (const m of state.meals) {
      if (!mealIndex.has(m.date)) mealIndex.set(m.date, []);
      mealIndex.get(m.date).push(m);
    }
    mealIndexOf = state.meals;
    mealIndexLen = state.meals.length;
  }
  return (mealIndex.get(day) || []).slice();
}
function newestMeals(list) {
  return list.slice().sort((a, b) => (b.id || 0) - (a.id || 0));
}
function dayWork(day) { return state.workouts.filter((w) => w.date === day); }
function sums(day) {
  const meals = dayMeals(day);
  return meals.reduce((a, m) => ({
    kcal: a.kcal + m.kcal, p: a.p + m.p, c: a.c + m.c, f: a.f + m.f,
  }), { kcal: 0, p: 0, c: 0, f: 0 });
}

let selectedDay = iso(new Date());
let draft = null;
let menuShotB64 = "";

const app = document.getElementById("app");

function render() {
  mealIndex = null;
  save();
  const setupScreens = ["setupLang", "setupDob", "setupName", "setupBody"];
  if (!state.setupDone && !setupScreens.includes(state.screen)) state.screen = "setupLang";
  if (state.setupDone && setupScreens.includes(state.screen)) state.screen = state.user ? "home" : "login";
  if (!state.user && state.screen !== "login" && state.screen !== "onboard" && !setupScreens.includes(state.screen)) state.screen = "login";
  if (state.screen === "pay") state.screen = state.user ? "home" : "login";   // ekran subskrypcji z wersji do 15.7
  const map = { login, onboard, home, history, activity, profile, addSheet, confirm, analyzing, more, meal, recipe, setupLang, setupDob, setupName, setupBody, goal: goalEdit, journey };
  if (state.screen !== "home") state.ideaBatch = null;
  app.innerHTML = "";
  settings();
  applyTheme();
  document.documentElement.lang = state.lang || "pl";
  if (window.MealquoNative && window.MealquoNative.setLang) window.MealquoNative.setLang(state.lang || "pl");
  if (window.MealquoNative && window.MealquoNative.setModel) window.MealquoNative.setModel(state.model === "flash" ? "flash" : "lite");
  document.querySelector("#phone > .lang")?.remove();
  map[state.screen]();
  backButton();
  movedCard();
  if (["home", "history", "activity", "profile", "journey"].includes(state.screen)) nav();
  syncReminders(false);
}

function accounts() {
  try { return JSON.parse(localStorage.getItem("mealquo_accounts") || "[]"); }
  catch { return []; }
}
function saveAccounts(list) { store("mealquo_accounts", JSON.stringify(list)); }
async function hashPass(s) {
  const b = new TextEncoder().encode("mealquo:" + s);
  const h = await crypto.subtle.digest("SHA-256", b);
  return [...new Uint8Array(h)].map((x) => x.toString(16).padStart(2, "0")).join("");
}
function readyUser(acc, extra) {
  const u = Object.assign({
    sex: "male", dob: "", height: 175, weight: 75,
    activity: "mid", goal: "keep", diet: "normal",
    plan: { kcal: 2000, p: 120, c: 220, f: 67 },
  }, acc.profile || {}, extra || {});
  if (state.body) {
    if (state.body.dob) u.dob = state.body.dob;
    if (state.body.height) u.height = state.body.height;
    if (state.body.weight) u.weight = state.body.weight;
  }
  u.email = acc.email;
  u.provider = acc.provider || "email";
  u.name = acc.name || (acc.email || "ty").split("@")[0];
  if (state.body && state.body.name && !u.displayName) u.displayName = String(state.body.name).slice(0, 40);
  u.age = ageFromDob(u.dob);
  u.plan = calcPlan(u);
  return u;
}
function ensurePick() {
  if (state.pick) return state.pick;
  const n = new Date();
  state.pick = { y: n.getFullYear() - 25, m: 6, d: 15, h: 170, w: 70 };
  return state.pick;
}
function monthNames() {
  return state.lang === "uk"
    ? ["січ", "лют", "бер", "кві", "тра", "чер", "лип", "сер", "вер", "жов", "лис", "гру"]
    : state.lang === "en"
    ? ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
    : ["sty", "lut", "mar", "kwi", "maj", "cze", "lip", "sie", "wrz", "paź", "lis", "gru"];
}
function setupChrome(step, title, sub) {
  return `<div class="setup">
    <div class="setup-dots">${[0, 1, 2, 3].map((i) => `<i class="${i === step ? "on" : ""}"></i>`).join("")}</div>
    <h1>${title}</h1>
    <p class="muted setup-sub">${sub}</p>`;
}
function setupLang() {
  const sys = systemLang();
  const rows = [
    ["en", "English"],
    ["pl", "Polski"],
    ["uk", "Українська"],
  ];
  app.insertAdjacentHTML("beforeend", setupChrome(0,
    L("Wybierz język", "Обери мову", "Choose your language"),
    L("Zaznaczony jest język telefonu.", "Позначено мову телефона.", "Your phone language is selected.")
  ) + `
    <div class="os-list">
      ${rows.map(([id, label]) => `<button type="button" class="os-row ${state.lang === id ? "on" : ""}" data-lang="${id}">
        <span class="os-flag">${langTag(id)}</span>
        <span class="os-copy"><b>${label}</b>${id === sys ? `<small>${L("Język systemowy", "Мова системи", "System language")}</small>` : ""}</span>
        <span class="os-tick">${state.lang === id ? icon("check") : ""}</span>
      </button>`).join("")}
    </div>
    <button class="primary setup-go" id="gonext">${L("Dalej", "Далі", "Continue")}</button>
  </div>`);
  app.querySelectorAll(".os-row").forEach((b) => {
    b.onclick = () => {
      state.lang = b.dataset.lang;
      state.langChosen = true;
      render();
    };
  });
  app.querySelector("#gonext").onclick = () => {
    state.langChosen = true;
    state.screen = "setupDob";
    render();
  };
}
function wheelHtml(id, values, selected, label) {
  return `<div class="wheel">
    <div class="wheel-lens"></div>
    <div class="wheel-col" data-col="${id}" data-sel="${selected}">
      <div class="wheel-pad"></div>
      ${values.map((v) => `<div class="wheel-item ${String(v) === String(selected) ? "on" : ""}" data-v="${v}">${label(v)}</div>`).join("")}
      <div class="wheel-pad"></div>
    </div>
  </div>`;
}
function bindWheels(onPick) {
  app.querySelectorAll(".wheel-col").forEach((col) => {
    const itemH = 46;
    const items = () => [...col.querySelectorAll(".wheel-item")];
    const mark = () => {
      const i = Math.max(0, Math.min(items().length - 1, Math.round(col.scrollTop / itemH)));
      items().forEach((el, idx) => el.classList.toggle("on", idx === i));
      const el = items()[i];
      if (el) onPick(col.dataset.col, el.dataset.v);
    };
    col.addEventListener("scroll", mark, { passive: true });
    const start = items().findIndex((el) => el.dataset.v === col.dataset.sel);
    requestAnimationFrame(() => {
      col.scrollTop = Math.max(0, start) * itemH;
      mark();
    });
  });
}
function setupDob() {
  const p = ensurePick();
  const yearNow = new Date().getFullYear();
  const years = [];
  for (let y = yearNow - 10; y >= yearNow - 90; y--) years.push(y);
  const months = Array.from({ length: 12 }, (_, i) => i + 1);
  const days = Array.from({ length: 31 }, (_, i) => i + 1);
  const names = monthNames();
  app.insertAdjacentHTML("beforeend", setupChrome(1,
    L("Data urodzenia", "Дата народження", "Date of birth"),
    L("Przewiń rok, miesiąc i dzień.", "Прокрути рік, місяць і день.", "Scroll the year, month and day.")
  ) + `
    <div class="wheels">
      ${wheelHtml("d", days, p.d, (v) => v)}
      ${wheelHtml("m", months, p.m, (v) => names[v - 1])}
      ${wheelHtml("y", years, p.y, (v) => v)}
    </div>
    <p class="muted age-msg" id="agemsg" hidden></p>
    <div class="setup-actions">
      <button class="soft" id="goback">${L("Wstecz", "Назад", "Back")}</button>
      <button class="primary" id="gonext">${L("Dalej", "Далі", "Continue")}</button>
    </div>
  </div>`);
  bindWheels((col, v) => { state.pick[col] = +v; });
  app.querySelector("#goback").onclick = () => { state.screen = "setupLang"; render(); };
  app.querySelector("#gonext").onclick = () => {
    const dim = new Date(state.pick.y, state.pick.m, 0).getDate();
    state.pick.d = Math.min(state.pick.d, dim);
    const dob = `${state.pick.y}-${String(state.pick.m).padStart(2, "0")}-${String(state.pick.d).padStart(2, "0")}`;
    const age = yearsOld(dob);
    const msg = app.querySelector("#agemsg");
    if (age != null && age < 13) {
      // poniżej 13 lat: bez konta, łagodnie
      msg.hidden = false;
      msg.textContent = L("Mealquo jest dla osób od 13 lat. Zajrzyj do nas za jakiś czas, a na razie jedz tak, jak radzą rodzice.", "Mealquo для осіб від 13 років. Завітай до нас трохи пізніше, а поки їж так, як радять батьки.", "Mealquo is for ages 13 and up. Come back in a while, and for now eat the way your parents suggest.");
      return;
    }
    if (age != null && age < 16) {
      msg.hidden = false;
      msg.textContent = L("Masz 13–15 lat, więc Mealquo działa w trybie nastolatka: bez diety i celu wagi, z misjami o zdrowych nawykach. Potrzebna będzie zgoda rodzica.", "Тобі 13–15 років, тож Mealquo працює в режимі підлітка: без дієти і цілі ваги, з місіями про здорові звички. Потрібна буде згода батьків.", "You're 13–15, so Mealquo runs in teen mode: no diet or weight goal, just healthy-habit missions. A parent's consent will be needed.");
      if (!state.pick.teenSeen) { state.pick.teenSeen = true; return; }
    }
    state.body = Object.assign({}, state.body, { dob });
    state.screen = "setupName";
    render();
  };
}
// imię (opcjonalnie): osobny krok po dacie urodzenia, można pominąć
function setupName() {
  app.insertAdjacentHTML("beforeend", setupChrome(2,
    L("Jak się do Ciebie zwracać?", "Як до тебе звертатися?", "What should we call you?"),
    L("Imię pojawi się w powitaniu. Możesz pominąć.", "Ім’я з’явиться у привітанні. Можна пропустити.", "Your name shows up in the greeting. You can skip this.")
  ) + `
    <input id="setname" maxlength="40" autocomplete="given-name" autocapitalize="words" placeholder="${L("np. Ania", "напр. Оля", "e.g. Anna")}" value="${attr((state.body && state.body.name) || "")}" style="font-size:20px;min-height:58px">
    <div class="setup-actions">
      <button class="soft" id="goback">${L("Wstecz", "Назад", "Back")}</button>
      <button class="primary" id="gonext">${L("Dalej", "Далі", "Continue")}</button>
    </div>
    <button class="ghost" id="goskip" style="margin-top:8px">${L("Pomiń", "Пропустити", "Skip")}</button>
  </div>`);
  const nameOf = () => String(app.querySelector("#setname").value || "").trim().slice(0, 40);
  app.querySelector("#goback").onclick = () => { state.body = Object.assign({}, state.body, { name: nameOf() }); state.screen = "setupDob"; render(); };
  app.querySelector("#gonext").onclick = () => { state.body = Object.assign({}, state.body, { name: nameOf() }); state.screen = "setupBody"; render(); };
  app.querySelector("#goskip").onclick = () => { state.body = Object.assign({}, state.body, { name: "" }); state.screen = "setupBody"; render(); };
  app.querySelector("#setname").onkeydown = (e) => { if (e.key === "Enter") { e.preventDefault(); app.querySelector("#gonext").click(); } };
}
function setupBody() {
  const p = ensurePick();
  const heights = [];
  for (let h = 140; h <= 220; h++) heights.push(h);
  const weights = [];
  for (let w = 40; w <= 180; w++) weights.push(w);
  app.insertAdjacentHTML("beforeend", setupChrome(3,
    L("Waga i wzrost", "Вага і зріст", "Weight and height"),
    L("Przewiń, aż liczba będzie Twoja.", "Прокрути до свого числа.", "Scroll until the number is yours.")
  ) + `
    <div class="wheels two">
      <div>
        <div class="wheel-label">${L("Wzrost", "Зріст", "Height")}</div>
        ${wheelHtml("h", heights, p.h, (v) => v + " cm")}
      </div>
      <div>
        <div class="wheel-label">${L("Waga", "Вага", "Weight")}</div>
        ${wheelHtml("w", weights, p.w, (v) => v + " kg")}
      </div>
    </div>
    <div class="setup-actions">
      <button class="soft" id="goback">${L("Wstecz", "Назад", "Back")}</button>
      <button class="primary" id="gonext">${L("Gotowe", "Готово", "Done")}</button>
    </div>
  </div>`);
  bindWheels((col, v) => { state.pick[col] = +v; });
  app.querySelector("#goback").onclick = () => { state.screen = "setupName"; render(); };
  app.querySelector("#gonext").onclick = () => {
    state.body = Object.assign({}, state.body, { height: state.pick.h, weight: state.pick.w });
    state.setupDone = true;
    state.langChosen = true;
    if (state.user) {
      state.user.dob = state.body.dob;
      state.user.height = state.body.height;
      state.user.weight = state.body.weight;
      state.user.age = ageFromDob(state.body.dob);
      if (state.body.name) state.user.displayName = state.body.name;
      state.user.plan = calcPlan(state.user);
      const list = accounts();
      const i = list.findIndex((a) => a.email === state.user.email);
      if (i >= 0) {
        list[i].profile = Object.assign({}, list[i].profile, {
          dob: state.user.dob, height: state.user.height, weight: state.user.weight,
          age: state.user.age, plan: state.user.plan,
        });
        saveAccounts(list);
      }
      state.screen = "home";
    } else state.screen = "login";
    render();
  };
}

// konto na serwerze dla tego e-maila i hasła: found, none, auth (inne hasło) albo off (brak serwera)
async function cloudAccount(email, hash) {
  if (!cloudSync()) return "off";
  const { status, data } = await cloudJournal({ action: "pull", email, hash });
  if (status === 403) return "auth";
  if (status !== 200) return "off";
  return data.found ? "found" : "none";
}
// konto z serwera zapisane na tym telefonie i wejście z jego dziennikiem
// konto z serwera v2: zapis w telefonie (logowanie offline) i synchronizacja od zera
function enterServerAccount(email, hash, token) {
  const list = accounts().filter((a) => a.email !== email);
  const acc = { email, hash, provider: "email", created: Date.now() };
  list.push(acc);
  saveAccounts(list);
  v2Store(email, { token, cursor: 0, synced: {} });
  enterAccount(acc, null, true);
}
// Android: hasło do Menedżera haseł Google (Credential Manager), wspólnego z Chrome dla mealquo.app (assetlinks.json)
let passFromManager = false;
function savePass(email, pass) {
  if (passFromManager) { passFromManager = false; return; }
  try { if (window.MealquoNative && MealquoNative.passwordSave) MealquoNative.passwordSave(email, pass); } catch (_) {}
}
function enterCloudAccount(email, hash) {
  const acc = { email, hash, provider: "email", created: Date.now() };
  const list = accounts().filter((a) => a.email !== email);
  list.push(acc);
  saveAccounts(list);
  enterAccount(acc, null, true);
}

function enterAccount(acc, extra, fromCloud) {
  emptyDiary();
  state.user = readyUser(acc, extra);
  const book = readBook(acc.email);
  if (book) applyBook(book);
  if (state.user) state.user.email = acc.email;
  state.screen = "home";
  state.setupDone = true;
  if (fromCloud) pulling = true;
  render();
  pullCloud(fromCloud);
}

let passAsked = false;
function login() {
  const g = `<svg width="18" height="18" viewBox="0 0 48 48" aria-hidden="true"><path fill="#FFC107" d="M43.6 20.5H42V20H24v8h11.3C33.7 32.7 29.3 36 24 36c-6.6 0-12-5.4-12-12s5.4-12 12-12c3.1 0 5.8 1.2 8 3.1l5.7-5.7C34.2 6.1 29.4 4 24 4 12.9 4 4 12.9 4 24s8.9 20 20 20 20-8.9 20-20c0-1.2-.1-2.3-.4-3.5z"/><path fill="#FF3D00" d="M6.3 14.7l6.6 4.8C14.7 16 19 12 24 12c3.1 0 5.8 1.2 8 3.1l5.7-5.7C34.2 6.1 29.4 4 24 4 16.3 4 9.6 8.3 6.3 14.7z"/><path fill="#4CAF50" d="M24 44c5.2 0 10-2 13.6-5.2l-6.3-5.3C29.2 35.1 26.7 36 24 36c-5.3 0-9.7-3.3-11.3-8l-6.5 5C9.5 39.6 16.2 44 24 44z"/><path fill="#1976D2" d="M43.6 20.5H42V20H24v8h11.3c-1 2.9-3.1 5.2-5.9 6.5l6.3 5.3C37.4 41.2 44 36 44 24c0-1.2-.1-2.3-.4-3.5z"/></svg>`;
  const a = `<svg width="16" height="18" viewBox="0 0 14 17" aria-hidden="true"><path fill="currentColor" d="M13.2 5.7c-.1.1-1.8 1-1.8 3.1 0 2.4 2.1 3.3 2.2 3.3-.1.2-.3 1.1-1.1 2.2-.7.9-1.4 1.9-2.5 1.9s-1.4-.6-2.6-.6-1.6.6-2.6.6-1.7-.9-2.5-1.9C1.2 13 0 10.4 0 7.9 0 5.1 1.8 3.6 3.5 3.6c1.1 0 2 .7 2.6.7.6 0 1.7-.8 3-.8 1.2 0 2.4.7 3.1 1.8-.1.1-1 1.4-1 1.4zM9.4 2.4c.5-.6.9-1.5.8-2.4-.8 0-1.7.5-2.3 1.2-.5.6-.9 1.5-.8 2.3.9.1 1.7-.4 2.3-1.1z"/></svg>`;
  app.insertAdjacentHTML("beforeend", `
    <div class="screen hero-login">
      <div class="login-hero">
        <div class="brand"><img class="logo-img" src="img/icon.png" alt="">${t("app")}</div>
        <h1>${L("Zrób zdjęcie talerza.<br>Resztę policzymy.", "Сфотографуй тарілку.<br>Решту порахуємо.", "Snap the plate.<br>We'll count the rest.")}</h1>
        <p>${L("Kalorie i makro ze zdjęcia, misje dnia i trener AI, który zna Twój dziennik.", "Калорії та макро з фото, місії дня і AI-тренер, який знає твій щоденник.", "Calories and macros from a photo, daily missions and an AI coach that knows your diary.")}</p>
      </div>
      ${socialButtons(g, a)}
      <label>${t("email")}</label>
      <input id="em" type="email" autocomplete="username" placeholder="ty@email.com" />
      <label>${t("password")}</label>
      <input id="pw" type="password" autocomplete="current-password" placeholder="••••••••" />
      <p class="muted" id="pwhint" style="display:none;margin:6px 0 0;font-size:13px">${L("Wpisz nowe hasło albo wybierz silne hasło podpowiedziane przez Google.", "Введи новий пароль або вибери надійний пароль, запропонований Google.", "Type a new password or pick the strong one suggested by Google.")}</p>
      <p class="muted" id="autherr" style="min-height:18px;margin:8px 0 0"></p>
      <button class="primary" id="in">${t("loginBtn")}</button>
      <div style="height:8px"></div>
      <button class="ghost" id="up">${t("register")}</button>
      <p class="muted" style="margin-top:14px;font-size:13px;text-align:center">${L("Zakładając konto, akceptujesz", "Створюючи акаунт, приймаєш", "By creating an account you accept the")} <a href="#" data-legal="privacy.html">${L("politykę prywatności", "політику конфіденційності", "privacy policy")}</a>.</p>
    </div>`);
  bindLegal();
  const err = (m) => { app.querySelector("#autherr").textContent = m || ""; };
  const emailOf = () => (app.querySelector("#em").value || "").trim().toLowerCase();
  const passOf = () => app.querySelector("#pw").value || "";
  // tryb zakładania konta: pole hasła jako „new-password”, więc Chrome/Google podpowiada silne hasło
  let signup = false;
  const signupMode = () => {
    signup = true;
    const pw = app.querySelector("#pw");
    pw.setAttribute("autocomplete", "new-password");
    app.querySelector("#pwhint").style.display = "";
    app.querySelector("#in").textContent = t("register");
    app.querySelector("#up").textContent = t("loginBtn");
    err("");
    (app.querySelector("#em").value ? pw : app.querySelector("#em")).focus();
  };
  const loginMode = () => {
    signup = false;
    app.querySelector("#pw").setAttribute("autocomplete", "current-password");
    app.querySelector("#pwhint").style.display = "none";
    app.querySelector("#in").textContent = t("loginBtn");
    app.querySelector("#up").textContent = t("register");
    err("");
  };
  const doLogin = async () => {
    const email = emailOf(), pass = passOf();
    if (!email.includes("@") || pass.length < 6) return err(t("weak"));
    const acc = accounts().find((a) => a.email === email);
    const hash = await hashPass(pass);
    // konto na serwerze (v2): tu sprawdzane jest hasło; bez sieci logowanie z pamięci telefonu
    const r = await cloudApi("/api/v2/login", { email, password: pass, device: v2Device() });
    if (r.status === 200 && r.data.token) { savePass(email, pass); return enterServerAccount(email, hash, r.data.token); }
    if (r.status === 401) { passFromManager = false; return err(t("passErr")); }
    if (r.status === 429) return err(L("Za dużo prób. Spróbuj za 15 minut.", "Забагато спроб. Спробуй за 15 хвилин.", "Too many tries. Try again in 15 minutes."));
    if (acc && acc.hash === hash) return enterAccount(acc);
    if (await cloudAccount(email, hash) === "found") return enterCloudAccount(email, hash);
    err(t("passErr"));
  };
  const doRegister = async () => {
    const email = emailOf(), pass = passOf();
    if (!email.includes("@") || pass.length < 6) return err(t("weak"));
    const list = accounts();
    if (list.some((a) => a.email === email)) return err(t("exists"));
    const hash = await hashPass(pass);
    const r = await cloudApi("/api/v2/register", { email, password: pass, device: v2Device() });
    if (r.status === 200 && r.data.token) { savePass(email, pass); return enterServerAccount(email, hash, r.data.token); }
    if (r.status === 401 || r.status === 409) return err(t("exists"));
    const cloud = await cloudAccount(email, hash);
    if (cloud === "auth") return err(t("exists"));
    if (cloud === "found") return enterCloudAccount(email, hash);
    const acc = { email, hash, provider: "email", created: Date.now() };
    list.push(acc);
    saveAccounts(list);
    enterAccount(acc);
  };
  app.querySelector("#in").onclick = () => (signup ? doRegister() : doLogin());
  // „Załóż konto” z wpisanym hasłem zakłada konto od razu; z pustym przełącza na zakładanie (podpowiedź silnego hasła)
  app.querySelector("#up").onclick = () => (signup ? loginMode() : passOf() ? doRegister() : signupMode());
  app.querySelector("#pw").onkeydown = (e) => { if (e.key === "Enter") app.querySelector("#in").click(); };
  // Android: zapisane hasła z Menedżera haseł Google (też te z Chrome dla mealquo.app)
  window.onSavedPassword = (email, pass) => {
    if (!app.querySelector("#em")) return;
    app.querySelector("#em").value = email;
    app.querySelector("#pw").value = pass;
    passFromManager = true;
    loginMode();
    doLogin();
  };
  if (!passAsked) {
    passAsked = true;
    try { if (window.MealquoNative && MealquoNative.passwordGet) MealquoNative.passwordGet(); } catch (_) {}
  }
  const google = app.querySelector("#google");
  if (google) google.onclick = () => {
    if (window.MealquoNative && window.MealquoNative.pickGoogle) {
      window.MealquoNative.pickGoogle();
      return;
    }
    err(L("Na APK wybierz konto Google z telefonu. Tu: załóż konto e-mail.", "На телефоні з APK вибери свій акаунт Google.", "On the app, pick the Google account on this phone. Here: use email."));
  };
  bindSocial(err);
  window.onGoogleAccount = (email) => {
    email = String(email || "").trim().toLowerCase();
    if (!email.includes("@")) return err(t("passErr"));
    const list = accounts();
    let acc = list.find((a) => a.email === email);
    if (!acc) {
      acc = { email, provider: "google", hash: "", created: Date.now(), name: email.split("@")[0] };
      list.push(acc);
      saveAccounts(list);
    }
    enterAccount(acc, { provider: "google" });
  };
}



