function askPlan() {
  const day = iso(new Date());
  if (!state.ask || state.ask.day !== day || !state.ask.hours) {
    const between = (a, b) => a + Math.floor(Math.random() * (b - a + 1));
    state.ask = { day, hours: [between(8, 11), between(13, 16), between(18, 21)], done: [], asked: [], quiet: 0, slot: 0 };
    save();
  }
  return state.ask;
}
function dueQuestion() {
  const plan = askPlan();
  if (plan.quiet && Date.now() < plan.quiet) return null;
  const h = new Date().getHours();
  const slot = plan.hours.findIndex((hour, i) => h >= hour && plan.done.indexOf(i) < 0);
  if (slot < 0) return null;
  plan.slot = slot;
  return nextTaste();
}
