  state.meals.push({
    id: Date.now(),
    date: selectedDay,
    time: new Date().toTimeString().slice(0, 5),
    title: name,
    comment: "",
    thumb: null,
    note: "",
    kcal: idea.kcal,
    p: idea.p,
    c: idea.c,
    f: idea.f,
    items: [{ n: name, g: idea.g || 200, kcal: idea.kcal, p: idea.p, c: idea.c, f: idea.f, mode: "g", count: 1, piece: idea.g || 200 }],
  });
