function whyToday(d) {
  const night = nightState();
  const leftK = Math.max(0, Math.round(+night.leftKcal || 0));
  const leftP = Math.max(0, Math.round(+night.leftP || 0));
  const kcal = Math.round(+d.kcal || 0);
  const p = Math.round(+d.p || 0);
  if (leftK <= 0) {
    return L(
      `Dziś limit kalorii już jest wykorzystany. To danie ma około ${kcal} kcal i byłoby ponad plan.`,
      `Сьогодні ліміт калорій уже вичерпано. Ця страва має близько ${kcal} ккал і буде понад план.`,
      `Today’s calorie limit is already used. This dish is about ${kcal} kcal and would be over the plan.`
    );
  }
  const after = leftK - kcal;
  if (kcal > 0 && after >= 0) {
    return L(
      `Zostało dziś ${leftK} kcal i ${leftP} g białka. To danie ma około ${kcal} kcal i ${p} g białka, więc jeszcze się mieści. Po nim zostanie około ${after} kcal.`,
      `Сьогодні лишилось ${leftK} ккал і ${leftP} г білка. Ця страва має близько ${kcal} ккал і ${p} г білка, тож ще вміщається. Після неї лишиться близько ${after} ккал.`,
      `You still have ${leftK} kcal and ${leftP} g of protein today. This dish is about ${kcal} kcal and ${p} g of protein, so it still fits. About ${after} kcal would be left.`
    );
  }
  const smaller = leftK;
  return L(
    `To danie ma około ${kcal} kcal, a zostało ${leftK}. Poproś o mniejszą porcję, około ${smaller} kcal, i wtedy jeszcze wejdzie w dzień.`,
    `Ця страва має близько ${kcal} ккал, а лишилось ${leftK}. Попроси меншу порцію, близько ${smaller} ккал, і тоді ще ввійде в день.`,
    `This dish is about ${kcal} kcal and you have ${leftK} left. Ask for a smaller plate, about ${smaller} kcal, and it still fits today.`
  );
}
