function icon(name, cls) {
  return `<svg class="ic${cls ? " " + cls : ""}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name] || ""}</svg>`;
}
const QUEST_ICON = { kcal: "target", protein: "egg", log3: "camera", veg: "leaf", move: "move", nosnack: "moon", breakfast: "sun", weigh: "scale", nodrink: "drop", steps: "steps" };
// kolorowa odznaka: krążek w kolorze i biała ikona (zamiast emoji)
function badgeArt(name, color, big) {
  return `<span class="badge-art${big ? " big" : ""}" style="--c:${color}">${icon(name)}</span>`;
}
// znacznik języka zamiast flagi
function langTag(id) { return `<span class="lang-tag">${id === "uk" ? "UK" : id === "en" ? "EN" : "PL"}</span>`; }
function questIcon(id) { return icon(QUEST_ICON[id] || "target"); }
function attr(s) {
  return String(s || "").replace(/&/g, "\u0026amp;").replace(/"/g, "\u0026quot;").replace(/</g, "\u0026lt;");
}
function dishCard(night, d, i, kind) {
  const shown = d.orig || d.en || L(d.pl, d.uk, d.en);
  const keyName = d.orig || d.pl || shown;
  const src = night.photos && night.photos[keyName];
  const face = src && String(src).indexOf("http") === 0
    ? `<img class="thumb" alt="" src="${attr(src)}">`
    : `<span class="food-ph"></span>`;
  return `<button type="button" class="idea dish" data-${kind}="${i}"><span class="thumb-slot" data-slot="${attr(keyName)}">${face}</span><span class="dish-copy"><b>${String(shown).replace(/</g, "")}</b><span class="dish-meta">${macroLine(d.p, d.c, d.f)}</span></span><b class="dish-kcal">${d.kcal}</b></button>`;
}
function askDishPhotos(list) {
  const night = nightState();
  night.photos = night.photos || {};
  (list || []).forEach((d) => {
    const key = d.orig || d.pl || d.en;
    if (!key || !d.photo || String(d.photo).indexOf("http") !== 0) return;
    night.photos[key] = d.photo;
  });
}
function eveningCard(left) {
  const slot = planSlot();
  if (selectedDay !== iso(new Date()) || !slot) return "";
  const night = nightState();
  night.leftKcal = left.kcal;
  night.leftP = left.p;
  night.leftC = left.c;
  const title = slot === "lunch"
    ? L("Przed lunchem", "Перед обідом", "Before lunch")
    : L("Plany na wieczór", "Плани на вечір", "Plans for tonight");
  const question = slot === "lunch"
    ? L("Co przed lunchem?", "Що перед обідом?", "What’s before lunch?")
    : L("Co dziś wieczorem?", "Що сьогодні ввечері?", "What’s tonight?");
  if (!night.mode) {
    return `<div class="section-title">${title}</div><div class="date-ask"><p>${question}</p><div class="row">
      <button type="button" class="chip" data-night="in">${L("Zostaję, zamówię", "Лишаюсь, замовлю", "Staying in, I’ll order")}</button>
      <button type="button" class="chip" data-night="cook">${L("Ugotuję", "Готуватиму", "I’ll cook")}</button>
      <button type="button" class="chip" data-night="out">${L("Restauracja", "Ресторан", "A restaurant")}</button>
    </div></div>`;
  }
  const gap = L(
    `Zostało około ${Math.max(0, Math.round(left.kcal))} kcal i ${Math.max(0, Math.round(left.p))} g białka.`,
    `Лишилось близько ${Math.max(0, Math.round(left.kcal))} ккал і ${Math.max(0, Math.round(left.p))} г білка.`,
    `About ${Math.max(0, Math.round(left.kcal))} kcal and ${Math.max(0, Math.round(left.p))} g of protein left.`
  );
  let body = "";
  if (night.mode === "in") {
    const shots = Array.isArray(night.shotDishes) ? night.shotDishes : [];
    body = `<p>${L("Możesz zamówić coś w tym rozmiarze, na przykład z Glovo, żeby domknąć dzień.", "Можеш замовити порцію такого розміру, наприклад з Glovo, щоб закрити день.", "Order about this much, for example on Glovo, to close the day.")}</p><p class="muted">${gap}</p>
      <button type="button" class="soft" id="menushot" style="margin-top:10px">${night.shotBusy ? L("Czytam kartę…", "Читаю меню…", "Reading the menu…") : L("Wklej zrzut restauracji", "Встав скрін закладу", "Paste a restaurant screenshot")}</button>
      ${night.shotName ? `<p class="muted" style="margin-top:8px">${String(night.shotName).replace(/</g, "")}</p>` : ""}`;
    if (shots.length) {
      body += shots.map((d, i) => `<button type="button" class="idea" data-shot="${i}"><b>${String(L(d.pl, d.uk, d.en)).replace(/</g, "")}</b><span>${d.kcal} kcal · ${macroLine(d.p, d.c, d.f)}</span></button>`).join("");
      body += `<button type="button" class="ghost" data-more="shot" style="margin-top:8px">${L("Wybierz inne", "Інші три", "Three others")}</button>`;
    } else {
      const dish = closestDish(ORDERS, left);
      night.pick = dish;
      if (dish) body += `<button type="button" class="idea" data-night-add="1"><b>${L(dish.pl, dish.uk, dish.en)}</b><span>${dish.kcal} kcal · ${macroLine(dish.p, dish.c, dish.f)}</span></button>`;
    }
  } else if (night.mode === "cook") {
    const have = new Set(night.fridge || []);
    body = `<p>${L("Co masz w lodówce?", "Що є в холодильнику?", "What’s in the fridge?")}</p><div class="row">${FRIDGE.map((f) => `<button type="button" class="chip ${have.has(f[0]) ? "on" : ""}" data-fridge="${f[0]}">${L(f[1], f[2], f[3])}</button>`).join("")}</div>`;
    if (have.size) {
      const hits = COOKS.filter((r) => r.need.every((n) => have.has(n)) && dietOk(r));
      const loose = COOKS.filter((r) => r.need.some((n) => have.has(n)) && dietOk(r));
      const dish = closestDish(hits.length ? hits : loose, left);
      night.pick = dish;
      if (dish) body += `<p class="muted" style="margin-top:8px">${L("Z tego da się zrobić:", "З цього вийде:", "You can make:")}</p><button type="button" class="idea" data-night-add="1"><b>${L(dish.pl, dish.uk, dish.en)}</b><span>${dish.kcal} kcal · ${macroLine(dish.p, dish.c, dish.f)}</span></button>`;
    }
  } else {
    const dishes = Array.isArray(night.mapDishes) ? night.mapDishes : [];
    const near = Array.isArray(night.near) ? night.near : [];
    const cards = dishes.map((d, i) => dishCard(night, d, i, "map")).join("");
    if (night.placeOn) {
      body = `<p><b>${String(night.mapName || "").replace(/</g, "")}</b></p>
        ${night.mapBusy ? `<div class="near-bar" id="mapbar"><span style="width:${Math.max(8, night.mapPct || 12)}%"></span></div><p class="muted" id="mapstep" style="margin-top:8px">${String(night.mapStep || L("Szukam karty…", "Шукаю меню…", "Reading the menu…")).replace(/</g, "")}</p>` : ""}
        ${cards}
        ${dishes.length ? `<button type="button" class="ghost" data-more="map" style="margin-top:8px">${L("Wybierz inne", "Інші три", "Three others")}</button>` : ""}
        <button type="button" class="ghost" id="nearback" style="margin-top:4px">${L("Inne lokale", "Інші заклади", "Other places")}</button>`;
    } else {
      body = `<p>${L("Jaka restauracja?", "Який заклад?", "Which kind of place?")}</p>
      <button type="button" class="primary" id="near" style="margin-top:8px">${night.nearBusy ? L("Szukam lokali obok…", "Шукаю заклади поруч…", "Looking nearby…") : L("Jestem w restauracji", "Я в закладі", "I’m at a restaurant")}</button>
      ${night.nearBusy ? `<div class="near-bar" id="nearbar"><span style="width:${Math.max(6, night.nearPct || 8)}%"></span></div><p class="muted" id="nearstep" style="margin-top:8px">${String(night.nearStep || L("Lokalizacja…", "Локація…", "Location…")).replace(/</g, "")}</p>` : ""}
      ${night.hereLabel ? `<p class="muted" style="margin-top:10px">${L("Szukam przy", "Шукаю біля", "Searching near")} ${String(night.hereLabel).replace(/</g, "")}</p>` : ""}
      ${near.map((p, i) => `<button type="button" class="idea" data-near="${i}"><b>${String(p.name || "").replace(/</g, "")}</b><br><span>${p.meters ? (p.meters < 1000 ? Math.round(p.meters) + " m" : (p.meters / 1000).toFixed(1) + " km") : ""}${p.address ? " · " + String(p.address).replace(/</g, "") : ""}</span></button>`).join("")}
      ${near.length ? `<button type="button" class="ghost" id="nearmore" style="margin-top:8px">${L("Pokaż więcej", "Показати ще", "Show more")}</button>` : ""}
      ${night.nearName && !near.length ? `<p class="muted" style="margin-top:8px">${String(night.nearName).replace(/</g, "")}</p>` : ""}
      <label style="display:block;margin-top:14px">${L("Link z Google Maps", "Посилання з Google Maps", "Google Maps link")}</label>
      <input id="maplink" type="url" inputmode="url" placeholder="https://maps.app.goo.gl/…" value="${attr((night.mapLink || "").includes("google.com/maps/search") ? "" : night.mapLink)}">
      <button type="button" class="primary" id="mapgo" style="margin-top:8px">${night.mapBusy ? L("Szukam karty…", "Шукаю меню…", "Reading the menu…") : L("Trzy dania z karty", "Три страви з меню", "Three dishes from the menu")}</button>
      ${night.mapBusy ? `<div class="near-bar" id="mapbar"><span style="width:${Math.max(8, night.mapPct || 12)}%"></span></div><p class="muted" id="mapstep" style="margin-top:8px">${String(night.mapStep || L("Czytam link…", "Читаю посилання…", "Reading the link…")).replace(/</g, "")}</p>` : ""}
      ${night.mapName ? `<p class="muted" style="margin-top:8px">${String(night.mapName).replace(/</g, "")}</p>` : ""}
      ${cards}
      ${dishes.length ? `<button type="button" class="ghost" data-more="map" style="margin-top:8px">${L("Wybierz inne", "Інші три", "Three others")}</button>` : ""}`;
    }
    if (!dishes.length && night.cuisine && MENUS[night.cuisine]) {
      const dish = closestDish(MENUS[night.cuisine].items, left);
      night.pick = dish;
      const smaller = dish && dish.kcal > left.kcal * 1.15;
      if (dish) body += `<p class="muted" style="margin-top:8px">${gap} ${smaller ? L("Poproś o mniejszą porcję.", "Попроси меншу порцію.", "Ask for a smaller plate.") : L("To mieści się w tym, co zostało.", "Це вміщується в залишок.", "This fits what’s left.")}</p><button type="button" class="idea" data-night-add="1"><b>${L(dish.pl, dish.uk, dish.en)}</b><span>${dish.kcal} kcal · ${macroLine(dish.p, dish.c, dish.f)}</span></button>`;
    }
  }
  return `<div class="section-title">${title}</div><div class="date-ask">${body}<button type="button" class="ghost" data-night="reset" style="margin-top:8px">${L("Zmień plan", "Змінити план", "Change the plan")}</button></div>`;
}

function home() {
  seedIfEmpty();
  gameTick();
  const plan = state.user.plan;
  const s = sums(selectedDay);
  pollSteps(false);
  const burn = dayBurn(selectedDay);
  const budget = plan.kcal + burn;
  const pct = Math.min(100, Math.round((s.kcal / budget) * 100));
  const meals = dayMeals(selectedDay);
  const stepsN = stepsOf(selectedDay);
  const stepsK = stepsKcal(selectedDay);
  const tip = advice(s, plan, meals);
  const ideas = ideasNow(Math.max(0, budget - s.kcal));
  const ask = dueQuestion();
  askPlace();
  const left = Math.round(budget - s.kcal);
  const lvl = levelInfo(state.points || 0);
  const qIds = dayQuests(selectedDay);
  const qDone = qIds.filter((id) => questState(id, selectedDay).done).length;
  const isToday = selectedDay === iso(new Date());
  const hour = new Date().getHours();
  const greet = !isToday ? dayLabel(selectedDay) : hour < 5 ? L("Dobrej nocy", "Доброї ночі", "Good night") : hour < 12 ? L("Dzień dobry", "Доброго ранку", "Good morning") : hour < 18 ? L("Cześć", "Привіт", "Hello") : L("Dobry wieczór", "Добрий вечір", "Good evening");
  const RING = 2 * Math.PI * 52;
  app.insertAdjacentHTML("beforeend", `
    <div class="screen home">
      <header class="home-top">
        <div class="home-hello">
          <p class="eyebrow">${isToday ? dayLabel(selectedDay) : L("Wybrany dzień", "Обраний день", "Selected day")}</p>
          <h1>${esc(greet)}${isToday && state.user.displayName ? `, ${esc(state.user.displayName)}` : ""}</h1>
        </div>
        <div class="home-actions">
          ${streakBadge()}
          <button type="button" class="lvl-btn" data-go="journey" aria-label="${attr(L("Twoja droga", "Твій шлях", "Your journey"))}" style="--p:${Math.max(4, lvl.pct)}%"><b>${lvl.level}</b></button>
        </div>
      </header>
      ${updateCard()}
      ${weekPills()}
      <section class="card hero ${left < 0 ? "over" : ""}">
        <div class="hero-top">
          <div class="hero-left">
            <span class="eyebrow">${left < 0 ? L("Ponad plan", "Понад план", "Over plan") : L("Zostało", "Лишилось", "Left")}</span>
            <div class="hero-num">${Math.abs(left)}<small>kcal</small></div>
            <p class="hero-sub">${L(`${Math.round(s.kcal)} zjedzone z ${budget}`, `${Math.round(s.kcal)} з’їдено з ${budget}`, `${Math.round(s.kcal)} eaten of ${budget}`)}${burn ? ` · ${L("ruch", "рух", "move")} +${burn}` : ""}</p>
            <div class="pills">
              ${plan.days ? `<span class="pill">${icon("target")}${plan.target} kg · ${plan.days} ${L("dni", "днів", "days")}</span>` : ""}
              ${stepsN != null ? `<span class="pill steps ${stepsN >= stepGoal().n ? "hit" : ""}" title="${attr(stepGoalWhy())}">${icon("steps")}${fmtSteps(stepsN)} / ${fmtSteps(stepGoal().n)} ${L("kroków", "кроків", "steps")}${stepsK ? ` · +${stepsK} kcal` : ""}</span>` : stepsSupported() && isToday && state.stepsStatus === "noperm" ? `<button type="button" class="pill steps ask" id="stepson">${icon("steps")}${L("Włącz kroki", "Увімкнути кроки", "Turn on steps")}</button>` : ""}
            </div>
          </div>
          <div class="ring-wrap" role="img" aria-label="${pct}%">
            <svg class="ring-svg" viewBox="0 0 120 120"><circle class="ring-bg" cx="60" cy="60" r="52"/><circle class="ring-fg" cx="60" cy="60" r="52" style="stroke-dasharray:${RING.toFixed(1)};stroke-dashoffset:${(RING * (1 - Math.min(100, pct) / 100)).toFixed(1)}"/></svg>
            <div class="ring-center"><b>${pct}<small>%</small></b></div>
          </div>
        </div>
        <div class="macro-bars">
          ${macroBar(t("protein"), s.p, plan.p, "var(--protein)")}
          ${macroBar(t("carbs"), s.c, plan.c, "var(--carbs)")}
          ${macroBar(t("fat"), s.f, plan.f, "var(--fat)")}
        </div>
      </section>
      <div class="sec"><h2>${L("Misje dnia", "Місії дня", "Today's missions")}</h2><button type="button" class="link" data-go="journey">${qDone}/${qIds.length} · ${L("Twoja droga", "Твій шлях", "Your journey")} ${icon("chevR")}</button></div>
      ${missionRow(selectedDay)}
      ${weighCard()}
      ${state.plateBusy && (+state.platePct || 0) < 100 ? `<div class="card busy-card"><div class="spinner"></div><div><b>${String(state.plateStep || L("Rozpoznaję danie…", "Розпізнаю страву…", "Reading the dish…")).replace(/</g, "")}</b><div class="near-bar" id="platebar"><span style="width:${Math.max(8, state.platePct || 12)}%"></span></div></div></div>` : ""}
      ${(state.pending || []).length ? `<div class="sec"><h2>${L("Po zjedzeniu", "Після їжі", "After you eat")}</h2></div><div class="card">${state.pending.map((p) => `<div class="pending"><div><b>${esc(p.title)}</b><p class="muted">${p.kcal} kcal</p></div><div class="row"><button type="button" class="chip on" data-ate="${p.id}">${L("Zjadłem", "З’їв", "I ate it")}</button><button type="button" class="chip" data-drop="${p.id}">${L("Nie", "Ні", "No")}</button></div></div>`).join("")}</div>` : ""}
      <div class="sec"><h2>${isToday ? L("Dziś na talerzu", "Сьогодні на тарілці", "On the plate today") : L("Na talerzu", "На тарілці", "On the plate")}</h2>${meals.length ? `<span class="muted">${meals.length} · ${Math.round(s.kcal)} kcal</span>` : ""}</div>
      ${meals.length ? `<div class="card list">${newestMeals(meals).map(mealRow).join("")}</div>` : `<div class="card empty">
        <div class="empty-art">${icon("camera")}</div>
        <b>${t("empty")}</b>
        <p>${L("Zrób zdjęcie talerza, powiedz albo wpisz, co było. Rozpoznam danie i policzę kalorie.", "Сфотографуй тарілку, скажи або впиши, що було. Розпізнаю страву і порахую калорії.", "Snap the plate, say or type what it was. I'll recognise the dish and count the calories.")}</p>
        <button type="button" class="primary" id="emptyadd">${icon("plus")}${L("Dodaj pierwszy posiłek", "Додати першу страву", "Add the first meal")}</button>
      </div>`}
      ${eveningCard({ kcal: Math.max(0, budget - s.kcal), p: Math.max(0, plan.p - s.p), c: Math.max(0, plan.c - s.c) })}
      <div class="sec"><h2>${slotTitle(ideas.slot)}</h2><span class="muted">${placeTitle(ideas.where)}</span></div>
      ${ask ? `<div class="date-ask"><p>${L(ask.q[0], ask.q[1], ask.q[2])}</p><div class="row">${tasteOpts(ask).map((o) => `<button type="button" class="chip" data-taste="${ask.id}" data-v="${o.v}">${o.label}</button>`).join("")}</div><p class="muted" style="margin:8px 0 0">${L("Poziom", "Рівень", "Level")} ${gameLevel()} · ${state.points || 0} pkt · ${L("runda", "раунд", "round")} ${state.round || 1}</p></div>` : ""}
      ${state.taste && state.taste.meat && !ask ? `<p class="muted" style="margin:-4px 0 8px">${L("Biorę pod uwagę to, co lubisz.", "Враховую те, що тобі до смаку.", "Using what you like.")}</p>` : ""}
      <div class="ideas">
        ${ideas.items.map((d, i) => {
          const key = d.pl || d.en || d.uk || "";
          const src = state.ideaPhotos && state.ideaPhotos[key];
          const face = src && String(src).indexOf("http") === 0 ? `<img class="thumb" alt="" src="${attr(src)}">` : `<span class="food-ph"></span>`;
          return `<button type="button" class="idea dish" data-idea="${i}"><span class="thumb-slot" data-slot="${attr(key)}">${face}</span><span class="dish-copy"><b>${L(d.pl, d.uk, d.en)}</b><span class="dish-meta">${Math.round(d.kcal)} kcal · ${macroLine(d.p, d.c, d.f)}</span></span></button>`;
        }).join("")}
      </div>
      ${coachTip(tip)}
    </div>`);
  bindMeals();
  bindGame();
  const emptyAdd = app.querySelector("#emptyadd");
  if (emptyAdd) emptyAdd.onclick = () => { state.screen = "addSheet"; render(); };
  const stepsOn = app.querySelector("#stepson");
  if (stepsOn) stepsOn.onclick = () => { try { MealquoNative.askSteps(); } catch (_) {} };
  bindUpdate();
  app.querySelectorAll(".date-pill").forEach((b) => {
    b.onclick = () => { selectedDay = b.dataset.d; render(); };
  });
  app.querySelectorAll("[data-idea]").forEach((b) => {
    b.onclick = () => holdIdea(ideas.items[+b.dataset.idea]);
  });
  state.ideaPhotos = state.ideaPhotos || {};
  if (state.photoRev !== 2) {
    state.ideaPhotos = {};
    state.photoRev = 2;
  }
  ideas.items.forEach((d) => {
    const key = d.pl || d.en || d.uk || "";
    if (!key || state.ideaPhotos[key]) return;
    const q = d.en || d.pl || key;
    if (window.MealquoNative && window.MealquoNative.dishPhoto) window.MealquoNative.dishPhoto(key, q);
  });
  app.querySelectorAll("[data-ate]").forEach((b) => {
    b.onclick = () => {
      const item = (state.pending || []).find((p) => String(p.id) === b.dataset.ate);
      state.pending = (state.pending || []).filter((p) => String(p.id) !== b.dataset.ate);
      if (item) addIdea(item);
      else render();
    };
  });
  app.querySelectorAll("[data-drop]").forEach((b) => {
    b.onclick = () => {
      state.pending = (state.pending || []).filter((p) => String(p.id) !== b.dataset.drop);
      render();
    };
  });
  app.querySelectorAll("[data-night]").forEach((b) => {
    b.onclick = () => {
      const night = nightState();
      night.mode = b.dataset.night === "reset" ? "" : b.dataset.night;
      night.cuisine = "";
      night.pick = null;
      night.mapLink = "";
      night.mapName = "";
      night.mapDishes = [];
      night.mapSeen = [];
      night.mapBusy = false;
      night.shotDishes = [];
      night.shotBusy = false;
      night.shotSeen = [];
      night.near = [];
      night.nearSeen = [];
      night.nearBusy = false;
      night.placeOn = false;
      night.nearKeep = null;
      menuShotB64 = "";
      render();
    };
  });
  app.querySelectorAll("[data-fridge]").forEach((b) => {
    b.onclick = () => {
      const night = nightState();
      const id = b.dataset.fridge;
      night.fridge = night.fridge || [];
      night.fridge = night.fridge.includes(id) ? night.fridge.filter((x) => x !== id) : night.fridge.concat(id);
      render();
    };
  });
  app.querySelectorAll("[data-cuisine]").forEach((b) => {
    b.onclick = () => {
      nightState().cuisine = b.dataset.cuisine;
      render();
    };
  });
  const nearBtn = app.querySelector("#near");
  if (nearBtn) nearBtn.onclick = () => {
    const night = nightState();
    night.nearBusy = true;
    night.nearPct = 8;
    night.nearStep = L("Lokalizacja…", "Локація…", "Location…");
    night.near = [];
    night.nearSeen = [];
    night.nearName = "";
    night._got = false;
    night._miss = 0;
    save();
    try {
      if (window.MealquoNative) window.MealquoNative.whereAmI();
    } catch (_) {}
    render();
    watchNear();
  };
  const nearMore = app.querySelector("#nearmore");
  if (nearMore) nearMore.onclick = () => {
    const night = nightState();
    const here = night.here;
    if (!here || !window.MealquoNative || !window.MealquoNative.placesNear) return;
    const seen = (night.nearSeen || []).concat((night.near || []).map((p) => p.name)).filter(Boolean);
    night.nearSeen = seen;
    night.nearBusy = true;
    night.nearPct = 40;
    night.nearStep = L("Szukam kolejnych lokali…", "Шукаю наступні заклади…", "Looking for more places…");
    night.near = [];
    save();
    render();
    window.MealquoNative.placesNear(here.lat, here.lon, seen.join(", "));
    watchNear();
  };
  function applyNear(packed) {
    const night = nightState();
    night.nearBusy = false;
    let data = {};
    try { data = JSON.parse(decodeURIComponent(escape(atob(packed)))); } catch (_) {}
    const seen = new Set((night.nearSeen || []).map((n) => String(n).toLowerCase()));
    night.near = (data.items || []).filter((x) => x && x.name && !seen.has(String(x.name).toLowerCase())).slice(0, 3).map((x) => ({
      name: x.name,
      address: x.address || "",
      maps: x.maps || "",
      meters: Math.round(+x.meters || 0),
    }));
    night.hereLabel = data.here || "";
    if (!night.near.length) {
      night.nearName = data.error === "location"
        ? L("Nie mam lokalizacji. Włącz GPS i spróbuj jeszcze raz.", "Немає локації. Увімкни GPS і спробуй ще.", "No location. Turn on GPS and try again.")
        : L("Nie widzę restauracji obok.", "Не бачу закладів поруч.", "No restaurants nearby.");
    }
    save();
    if (state.screen === "home") render();
  }
  function watchNear() {
    const started = Date.now();
    const tick = () => {
      const night = nightState();
      if (!night.nearBusy) return;
      let raw = "";
      try { raw = String(window.MealquoNative.nearPulse()); } catch (_) { raw = ""; }
      const parts = String(raw).split("\u001f");
      const gen = parts[0] || "";
      const pct = +parts[1] || 0;
      const label = parts[2] || "";
      const packed = parts.slice(3).join("\u001f");
      if (pct) {
        night.nearPct = pct;
        if (label) night.nearStep = label;
        const bar = app.querySelector("#nearbar span");
        const step = app.querySelector("#nearstep");
        if (bar) bar.style.width = Math.max(6, pct) + "%";
        if (step && label) step.textContent = label;
      }
      if (packed && window._nearGot !== gen) {
        window._nearGot = gen;
        applyNear(packed);
        return;
      }
      if (Date.now() - started > 40000) {
        night.nearBusy = false;
        night.nearName = L("Nie udało się znaleźć lokali.", "Не вдалося знайти заклади.", "Could not find places.");
        save();
        if (state.screen === "home") render();
        return;
      }
      setTimeout(tick, 300);
    };
    setTimeout(tick, 200);
  }
  window.onNearProgress = (pct, label) => {
    const night = nightState();
    night.nearPct = pct;
    night.nearStep = label || night.nearStep;
    const bar = app.querySelector("#nearbar span");
    const step = app.querySelector("#nearstep");
    if (bar) bar.style.width = Math.max(6, pct) + "%";
    if (step && label) step.textContent = label;
  };
  window.onMapProgress = (pct, label) => {
    const night = nightState();
    night.mapPct = pct;
    if (label) night.mapStep = label;
    const bar = app.querySelector("#mapbar span");
    const step = app.querySelector("#mapstep");
    if (bar) bar.style.width = Math.max(8, pct) + "%";
    if (step && label) step.textContent = label;
  };
  window.onHere = (lat, lon) => {
    const night = nightState();
    if (night._got) return;
    if (!lat || !lon) {
      night._miss = (night._miss || 0) + 1;
      if (night._miss < 2) return;
      night.nearBusy = false;
      night.nearName = L("Nie mam lokalizacji. Włącz GPS i spróbuj jeszcze raz.", "Немає локації. Увімкни GPS і спробуй ще.", "No location. Turn on GPS and try again.");
      save();
      if (state.screen === "home") render();
      return;
    }
    night._got = true;
    night.here = { lat: +lat, lon: +lon };
    if (window.MealquoNative && window.MealquoNative.placesNear) {
      window.MealquoNative.placesNear(+lat, +lon, (night.nearSeen || []).join(", "));
    }
  };
  window.onNearby = (packed) => {
    if (!packed || window._nearGot === "js") return;
    window._nearGot = "js";
    applyNear(packed);
  };
  app.querySelectorAll("[data-near]").forEach((b) => {
    b.onclick = () => {
      const night = nightState();
      const place = (night.near || [])[+b.dataset.near];
      if (!place || !window.MealquoNative || !window.MealquoNative.menuFromLink) return;
      const link = /^https?:\/\//i.test(place.maps || "")
        ? place.maps
        : "https://www.google.com/maps/search/?api=1&query=" + encodeURIComponent(place.name + " " + (place.address || ""));
      night.mapLink = link;
      night.mapName = place.name;
      night.placeOn = true;
      night.nearKeep = night.near;
      night.mapBusy = true;
      night.mapDishes = [];
      night.mapSeen = [];
      save();
      render();
      window.MealquoNative.menuFromLink(link, Math.round(night.leftKcal || 600), Math.round(night.leftP || 30), Math.round(night.leftC || 40), (state.user && state.user.diet) || "normal", "");
      watchMap();
    };
  });
  const mapGo = app.querySelector("#mapgo");
  if (mapGo) mapGo.onclick = () => {
    const input = app.querySelector("#maplink");
    const url = ((input && input.value) || "").trim();
    if (!/^https?:\/\//i.test(url)) return;
    const night = nightState();
    night.mapLink = url;
    night.mapBusy = true;
    night.mapPct = 12;
    night.mapStep = L("Czytam link…", "Читаю посилання…", "Reading the link…");
    night.mapName = "";
    night.mapDishes = [];
    night.mapSeen = [];
    save();
    try {
      if (window.MealquoNative) window.MealquoNative.menuFromLink(url, Math.round(night.leftKcal || 600), Math.round(night.leftP || 30), Math.round(night.leftC || 40), (state.user && state.user.diet) || "normal", "");
    } catch (_) {}
    render();
    watchMap();
  };
  function watchMap() {
    const started = Date.now();
    const tick = () => {
      const night = nightState();
      if (!night.mapBusy) return;
      let raw = "";
      try { raw = String(window.MealquoNative.mapPulse()); } catch (_) { raw = ""; }
      const parts = String(raw).split("\u001f");
      const gen = parts[0] || "";
      const pct = +parts[1] || 0;
      const label = parts[2] || "";
      const packed = parts.slice(3).join("\u001f");
      if (pct) {
        night.mapPct = pct;
        if (label) night.mapStep = label;
        const bar = app.querySelector("#mapbar span");
        const step = app.querySelector("#mapstep");
        if (bar) bar.style.width = Math.max(8, pct) + "%";
        if (step && label) step.textContent = label;
      }
      if (packed && window._mapGot !== gen) {
        window._mapGot = gen;
        window.onMapMenu(packed);
        return;
      }
      if (Date.now() - started > 28000) {
        night.mapBusy = false;
        night.mapName = L("Nie znalazłem karty. Spróbuj jeszcze raz.", "Не знайшов меню. Спробуй ще.", "Couldn't read the menu. Try again.");
        save();
        if (state.screen === "home") render();
        return;
      }
      setTimeout(tick, 300);
    };
    setTimeout(tick, 200);
  }
  window.onMapMenu = (packed) => {
    const night = nightState();
    night.mapBusy = false;
    let data = {};
    try { data = JSON.parse(decodeURIComponent(escape(atob(packed)))); } catch (_) {}
    const items = Array.isArray(data.items) ? data.items : [];
    const seen = new Set((night.mapSeen || []).map((n) => String(n).toLowerCase()));
    night.mapName = data.place || night.mapName || "";
    night.mapDishes = items.filter((x) => x && (x.name || x.name_pl || x.name_en) && !seen.has(String(x.name || x.name_pl || x.name_en).toLowerCase())).slice(0, 3).map((x) => ({
      orig: x.name || x.name_en || x.name_pl,
      pl: x.name_pl || x.name_en || x.name,
      uk: x.name_uk || x.name_pl || x.name_en || x.name,
      en: x.name_en || x.name || x.name_pl,
      photo: x.photo_url || "",
      g: Math.round(+x.grams || 250),
      kcal: Math.round(+x.kcal || 0),
      p: Math.round(+x.p || 0),
      c: Math.round(+x.c || 0),
      f: Math.round(+x.f || 0),
    }));
    night.mapDishes.forEach((d) => {
      if (d.photo && d.orig) {
        night.photos = night.photos || {};
        night.photos[d.orig] = d.photo;
      }
    });
    if (!night.mapDishes.length) {
      night.mapName = L("Nie znalazłem karty tego miejsca. Spróbuj innego linku.", "Не знайшов меню цього місця. Спробуй інше посилання.", "Couldn't read that menu. Try another link.");
    }
    save();
    if (state.screen === "home") render();
  };
  app.querySelectorAll("[data-map]").forEach((b) => {
    b.onclick = () => {
      const dish = (nightState().mapDishes || [])[+b.dataset.map];
      if (dish) holdIdea(dish);
    };
  });
  const nearBack = app.querySelector("#nearback");
  if (nearBack) nearBack.onclick = () => {
    const night = nightState();
    night.placeOn = false;
    night.mapBusy = false;
    night.mapDishes = [];
    night.mapName = "";
    if (night.nearKeep) night.near = night.nearKeep;
    save();
    render();
  };
  askDishPhotos(nightState().mapDishes);
  window.onDishPhoto = (key, url) => {
    const night = nightState();
    night.photos = night.photos || {};
    if (url) {
      night.photos[key] = url;
      state.ideaPhotos = state.ideaPhotos || {};
      state.ideaPhotos[key] = url;
    }
    else delete night.photos[key];
    const slots = app.querySelectorAll(".thumb-slot");
    slots.forEach((slot) => {
      if (slot.getAttribute("data-slot") !== key || !url) return;
      slot.innerHTML = `<img class="thumb" alt="" src="${attr(url)}">`;
    });
  };
  const menuShot = app.querySelector("#menushot");
  if (menuShot) menuShot.onclick = () => {
    const night = nightState();
    night.shotBusy = true;
    save();
    render();
    if (window.MealquoNative && window.MealquoNative.pickMenuShot) {
      const night = nightState();
      window.MealquoNative.pickMenuShot(Math.round(night.leftKcal || 600), Math.round(night.leftP || 30), Math.round(night.leftC || 40), (state.user && state.user.diet) || "normal");
    }
  };
  app.querySelectorAll("[data-shot]").forEach((b) => {
    b.onclick = () => {
      const dish = (nightState().shotDishes || [])[+b.dataset.shot];
      if (dish) holdIdea(dish);
    };
  });
  app.querySelectorAll("[data-more]").forEach((b) => {
    b.onclick = () => {
      const night = nightState();
      const diet = (state.user && state.user.diet) || "normal";
      const kcal = Math.round(night.leftKcal || 600);
      const p = Math.round(night.leftP || 30);
      const c = Math.round(night.leftC || 40);
      if (b.dataset.more === "map") {
        const seen = (night.mapSeen || []).concat((night.mapDishes || []).map((d) => d.pl)).filter(Boolean);
        night.mapSeen = seen;
        night.mapBusy = true;
        night.mapDishes = [];
        save();
        render();
        if (window.MealquoNative && window.MealquoNative.menuFromLink) {
          window.MealquoNative.menuFromLink(night.mapLink || "", kcal, p, c, diet, seen.join(", "));
          watchMap();
        }
        return;
      }
      const seen = (night.shotSeen || []).concat((night.shotDishes || []).map((d) => d.pl)).filter(Boolean);
      night.shotSeen = seen;
      night.shotBusy = true;
      night.shotDishes = [];
      save();
      render();
      if (window.MealquoNative && window.MealquoNative.readMenu && menuShotB64) {
        window.MealquoNative.readMenu(menuShotB64, kcal, p, c, diet, seen.join(", "));
      }
    };
  });
  window.onMenuImage = (dataUrl) => {
    const night = nightState();
    if (!dataUrl) {
      night.shotBusy = false;
      save();
      if (state.screen === "home") render();
      return;
    }
    const comma = String(dataUrl).indexOf(",");
    menuShotB64 = comma >= 0 ? String(dataUrl).slice(comma + 1) : String(dataUrl);
    night.shotSeen = [];
    night.shotDishes = [];
    night.shotBusy = true;
    save();
    if (window.MealquoNative && window.MealquoNative.readMenu) {
      window.MealquoNative.readMenu(menuShotB64, Math.round(night.leftKcal || 600), Math.round(night.leftP || 30), Math.round(night.leftC || 40), (state.user && state.user.diet) || "normal", "");
    }
  };
  window.onMenuShot = (packed) => {
    const night = nightState();
    night.shotBusy = false;
    let data = {};
    try { data = JSON.parse(decodeURIComponent(escape(atob(packed)))); } catch (_) {}
    const items = Array.isArray(data.items) ? data.items : [];
    const seen = new Set((night.shotSeen || []).map((n) => String(n).toLowerCase()));
    night.shotName = data.place || night.shotName || "";
    night.shotDishes = items.filter((x) => x && (x.name_pl || x.name_en) && !seen.has(String(x.name_pl || x.name_en).toLowerCase())).slice(0, 3).map((x) => ({
      pl: x.name_pl || x.name_en,
      uk: x.name_uk || x.name_pl || x.name_en,
      en: x.name_en || x.name_pl,
      g: Math.round(+x.grams || 250),
      kcal: Math.round(+x.kcal || 0),
      p: Math.round(+x.p || 0),
      c: Math.round(+x.c || 0),
      f: Math.round(+x.f || 0),
    }));
    if (!night.shotDishes.length) night.shotName = L("Nie widzę dań na tym zrzucie.", "Не бачу страв на цьому скріні.", "I can't see dishes on that screenshot.");
    save();
    if (state.screen === "home") render();
  };
  const addNight = app.querySelector("[data-night-add]");
  if (addNight) addNight.onclick = () => {
    const dish = nightState().pick;
    if (dish) holdIdea(dish);
  };
  app.querySelectorAll("[data-taste]").forEach((b) => {
    b.onclick = () => {
      if (b.dataset.taste === "pair" && state.ask && state.ask.pending) {
        const pair = state.ask.pending.pair || [];
        const v = b.dataset.v;
        state.likes = state.likes || {};
        state.pairs = state.pairs || [];
        const key = pair.slice().sort().join("|");
        if (key && !state.pairs.includes(key)) state.pairs.push(key);
        if (v === "tie") pair.forEach((id) => { state.likes[id] = (state.likes[id] || 0) + 1; });
        else if (v) state.likes[v] = (state.likes[v] || 0) + 1;
        state.points = (state.points || 0) + (v === "tie" ? 6 : 10);
        const meat = topLikedMeat();
        if (meat) state.taste = Object.assign({}, state.taste, { meat });
        state.ask.pending = null;
      } else {
        state.taste = Object.assign({}, state.taste, { [b.dataset.taste]: b.dataset.v });
      }
      const plan = state.ask;
      if (plan) {
        if (plan.done.indexOf(plan.slot) < 0) plan.done.push(plan.slot);
        plan.asked = (plan.asked || []).concat(b.dataset.taste);
        plan.quiet = Date.now() + 3 * 60 * 60 * 1000;
      }
      render();
    };
  });
}

// --- kroki (Health Connect na Androidzie, HealthKit w aplikacji iOS) ---
// cel kroków: ustala trener co tydzień (coach.week.stepsGoal); zanim ustali – średnia z 7 dni + 10%, do 500, 4000–12000, bez danych 6000
const STEP_MIN = 4000, STEP_MAX = 12000;
function stepsAvg(days) {
  const today = iso(new Date());
  const vals = [];
  for (let i = 1; i <= (days || 7); i++) { const n = stepsOf(shiftDay(today, -i)); if (n != null) vals.push(n); }
  return vals.length ? Math.round(vals.reduce((a, b) => a + b, 0) / vals.length) : null;
}
function stepGoal() {
  const avg = stepsAvg(7);
  const c = state.coach && state.coach.week;
  const fromCoach = c && c.start === weekStart(iso(new Date())) && +c.stepsGoal >= STEP_MIN && +c.stepsGoal <= STEP_MAX;
  if (fromCoach) return { n: Math.round(+c.stepsGoal / 500) * 500, src: "coach", why: String(c.stepsWhy || ""), avg };
  if (avg == null) return { n: 6000, src: "auto", why: "", avg: null };
  const n = Math.max(STEP_MIN, Math.min(STEP_MAX, Math.round((avg * 1.1) / 500) * 500));
  return { n, src: "auto", why: "", avg };
}
function fmtSteps(n) { return (+n || 0).toLocaleString(state.lang === "en" ? "en-GB" : "pl-PL"); }
function stepGoalWhy() {
  const g = stepGoal();
  if (g.src === "coach") return g.why || L(`Trener: ${fmtSteps(g.n)} kroków w tym tygodniu${g.avg != null ? ` – Twoja średnia to ${fmtSteps(g.avg)}` : ""}.`, `Тренер: ${fmtSteps(g.n)} кроків цього тижня${g.avg != null ? ` – твоє середнє ${fmtSteps(g.avg)}` : ""}.`, `Coach: ${fmtSteps(g.n)} steps this week${g.avg != null ? ` – your average is ${fmtSteps(g.avg)}` : ""}.`);
  if (g.avg != null) return L(`Z Twojej średniej ${fmtSteps(g.avg)} kroków plus 10%. Trener ustali cel na tydzień.`, `З твого середнього ${fmtSteps(g.avg)} кроків плюс 10%. Тренер поставить ціль на тиждень.`, `From your average of ${fmtSteps(g.avg)} steps plus 10%. The coach will set a weekly goal.`);
  return L("Cel startowy, póki telefon nie zbierze kilku dni kroków.", "Стартова ціль, поки телефон не збере кілька днів кроків.", "A starting goal until your phone has a few days of steps.");
}
function stepsSupported() { return !!(window.MealquoNative && MealquoNative.readSteps); }
function stepsMap() { return state.steps && typeof state.steps === "object" ? state.steps : (state.steps = {}); }
function stepsOf(day) {
  const e = stepsMap()[day];
  return e && e.n >= 0 ? e.n : null;
}
// telefon liczy kroki (jakiś wpis z ostatnich 3 dni) – wtedy misja kroków ma sens
function stepsAvailable() {
  const today = iso(new Date());
  return [0, 1, 2].some((n) => stepsOf(shiftDay(today, -n)) != null);
}
let stepsAskedAt = 0;
function pollSteps(force) {
  if (!stepsSupported() || !state.user) return;
  if (!force && Date.now() - stepsAskedAt < 10 * 60 * 1000) return;
  stepsAskedAt = Date.now();
  try { MealquoNative.readSteps(iso(new Date())); } catch (_) {}
}
window.onSteps = (day, n, status) => {
  state.stepsStatus = status || "ok";
  if (!(n >= 0)) { if (state.screen === "profile") render(); return; }
  const map = stepsMap();
  const prev = map[day] && map[day].n;
  map[day] = { n: Math.round(n), at: Date.now() };
  const keep = shiftDay(iso(new Date()), -60);
  Object.keys(map).forEach((d) => { if (d < keep) delete map[d]; });
  if (prev !== Math.round(n)) { save(); if (state.screen === "home" || state.screen === "journey" || state.screen === "history") render(); }
};
window.onStepsPerm = () => { stepsAskedAt = 0; pollSteps(true); };
document.addEventListener("visibilitychange", () => { if (document.visibilityState === "visible") pollSteps(false); });
// kroki policzone już w zapisanych spacerach/biegach tego dnia (żeby nie liczyć dwa razy)
function workoutSteps(day) {
  return dayWork(day).reduce((a, w) => {
    const n = String(w.name || "").toLowerCase();
    const run = /bieg|run|jog|біг|бег/.test(n);
    const walk = /spacer|walk|nordic|hik|marsz|schod|stair|прогул|ход|хайк/.test(n);
    if (!run && !walk) return a;
    const amount = +w.amount || 0;
    if (w.unit === "km") return a + amount * 1300;
    return a + amount * (run ? 160 : 100);
  }, 0);
}
// kcal netto z kroków poza treningami: ok. 0,00035 kcal na krok i kg masy ciała
// (marsz ~0,5 kcal/kg/km brutto przy ~1300 krokach na km daje ~0,00038; po odjęciu spoczynku ~0,00035)
function stepsKcal(day) {
  const n = stepsOf(day);
  if (n == null) return 0;
  const weight = +((state.user && state.user.weight) || 70);
  return Math.round(Math.max(0, n - workoutSteps(day)) * 0.00035 * weight);
}
function dayBurn(day) {
  return dayWork(day).reduce((a, w) => a + (+w.kcal || 0), 0) + stepsKcal(day);
}
function macroBar(label, val, goal, color) {
  const p = Math.min(100, Math.round((val / (goal || 1)) * 100));
  return `<div class="mbar">
    <span class="mbar-label">${label}</span>
    <b class="mbar-val">${Math.round(val)}<small> / ${goal} g</small></b>
    <div class="mbar-track"><i style="width:${Math.max(2, p)}%;background:${color}"></i></div>
  </div>`;
}
// „niedziela, 8 listopada” w języku aplikacji
function dayLabel(day) {
  const d = new Date(day + "T12:00:00");
  const loc = state.lang === "uk" ? "uk-UA" : state.lang === "en" ? "en-GB" : "pl-PL";
  try {
    const text = d.toLocaleDateString(loc, { weekday: "long", day: "numeric", month: "long" });
    return text.charAt(0).toUpperCase() + text.slice(1);
  } catch (_) { return day; }
}

function gramNum(n) {
  const v = Math.round((+n || 0) * 10) / 10;
  const text = v >= 10 ? String(Math.round(v)) : String(v);
  return text.replace(".", ",");
}
function macroLine(p, c, f) {
  const s = "\u00a0";
  return L(
    `Białko${s}${gramNum(p)}${s}g · Węgle${s}${gramNum(c)}${s}g · Tłuszcz${s}${gramNum(f)}${s}g`,
    `Білок${s}${gramNum(p)}${s}г · Вуглеводи${s}${gramNum(c)}${s}г · Жир${s}${gramNum(f)}${s}г`,
    `Protein${s}${gramNum(p)}${s}g · Carbs${s}${gramNum(c)}${s}g · Fat${s}${gramNum(f)}${s}g`
  );
}
function amountLine(it) {
  const g = Math.round(+it.g || 0);
  const n = Math.max(1, Math.round(+it.count || 1));
  if (it.mode === "szt") return g ? `${n} szt · ${g} g` : `${n} szt`;
  return n > 1 ? `${g} g · ${n} szt` : `${g} g`;
}
function portionText(m) {
  const items = m.items || [];
  const g = Math.round(items.reduce((a, i) => a + (+i.g || 0), 0));
  const pieces = items.filter((it) => it.mode === "szt");
  const clock = m.time || "";
  if (items.length && pieces.length === items.length) {
    const n = pieces.reduce((a, it) => a + (+it.count || 1), 0);
    const bit = `${n} szt${g ? " · " + g + " g" : ""}`;
    return clock ? `${clock} · ${bit}` : bit;
  }
  if (g > 0) return clock ? `${clock} · ${g} g` : `${g} g`;
  return clock;
}
function phoneStub(it) {
  const n = String(it.name_pl || it.name || it.name_en || "").toLowerCase();
  return (n === "wino" || n === "wine" || n === "вино") && +it.kcal === 125 && +it.p === 0 && +it.c === 4;
}
function mealRow(m) {
  const img = m.thumb
    ? `<img class="thumb" src="${attr(m.thumb)}" alt="" onerror="this.style.visibility='hidden'">`
    : `<div class="thumb thumb-ph">${icon("plate")}</div>`;
  return `<button type="button" class="meal" data-meal="${m.id}">
    ${img}
    <div><h3>${esc(m.title)}</h3><p>${portionText(m)}</p><p class="macros-line">${macroLine(m.p, m.c, m.f)}</p></div>
    <b>${Math.round(m.kcal)}</b>
  </button>`;
}
function bindMeals() {
  app.querySelectorAll("[data-meal]").forEach((b) => {
    b.onclick = () => { state.openId = +b.dataset.meal; state.screen = "meal"; render(); };
  });
}

function advice(s, plan, meals) {
  const goal = (state.user && state.user.goal) || "keep";
  const burn = dayBurn(selectedDay);
  const budget = plan.kcal + burn;
  const leftK = Math.round(budget - s.kcal);
  const leftP = Math.max(0, Math.round(plan.p - s.p));
  const leftC = Math.max(0, Math.round(plan.c - s.c));
  const room = Math.max(0, leftK);
  if (!meals.length) return L(
    "Dzień pusty. Zostało " + room + " kcal i " + leftP + " g białka.",
    "День порожній. Залишилось " + room + " ккал і " + leftP + " г білка.",
    "Nothing logged. " + room + " kcal and " + leftP + " g of protein left.");
  const weak = meals.slice().reverse().find((m) => (+m.p || 0) < 3 && (+m.kcal || 0) >= 40);
  const name = weak ? weak.title : "";
  if (goal === "lose" && s.kcal > budget * 0.85 && name) return L(
    name + " mogło poczekać. Zostało " + room + " kcal, a białka jeszcze " + leftP + " g. Dalej lepiej jajka, twaróg albo kurczak.",
    name + " могло почекати. Залишилось " + room + " ккал, а білка ще " + leftP + " г. Далі краще яйце, сир чи курка.",
    name + " could have waited. " + room + " kcal left and still " + leftP + " g of protein. Eggs, curd or chicken fit better.");
  if (leftP > plan.p * 0.4 && name) return L(
    name + " prawie nie ruszyło białka. Zostało " + leftP + " g białka i " + room + " kcal. Na kolejny raz jajka, twaróg, kurczak albo tofu.",
    name + " майже не дало білка. Залишилось " + leftP + " г білка і " + room + " ккал. Далі яйце, сир, курка або тофу.",
    name + " barely added protein. " + leftP + " g and " + room + " kcal left. Next: eggs, curd, chicken or tofu.");
  if (goal === "gain" && leftK > budget * 0.4) return L(
    "Zostało " + room + " kcal i " + leftP + " g białka. " + (name ? name + " tego nie dociągnie. " : "") + "Dorzuć ryż, orzechy albo pełny posiłek.",
    "Залишилось " + room + " ккал і " + leftP + " г білка. " + (name ? name + " цього не закриє. " : "") + "Додай рис, горіхи або повну страву.",
    room + " kcal and " + leftP + " g of protein left. " + (name ? name + " will not close that. " : "") + "Add rice, nuts or a full meal.");
  if (state.user && state.user.diet === "dia" && leftC < plan.c * 0.25) return L(
    "Węgli zostało " + leftC + " g. Dalej białko i warzywa, bez słodkiego.",
    "Вуглеводів лишилось " + leftC + " г. Далі білок і овочі, без солодкого.",
    leftC + " g of carbs left. Next: protein and vegetables, nothing sweet.");
  if (room < 280 && leftP > 20) return L(
    "Zostało " + room + " kcal i jeszcze " + leftP + " g białka. Mała porcja: twaróg, jajko albo jogurt.",
    "Залишилось " + room + " ккал і ще " + leftP + " г білка. Мала порція: сир, яйце або йогурт.",
    room + " kcal left and still " + leftP + " g of protein. A small portion: curd, an egg or yogurt.");
  return L(
    "Zostało " + room + " kcal, białka " + leftP + " g, węgli " + leftC + " g.",
    "Залишилось " + room + " ккал, білка " + leftP + " г, вуглеводів " + leftC + " г.",
    room + " kcal left, protein " + leftP + " g, carbs " + leftC + " g.");
}

let diaryOpen = "";
function history() {
  const plan = state.user.plan.kcal;
  const today = iso(new Date());
  if (!diaryOpen) diaryOpen = today;
  const days = [];
  for (let i = 6; i >= 0; i--) {
    const id = shiftDay(today, -i);
    const sm = sums(id);
    days.push({ id, kcal: Math.round(sm.kcal), p: Math.round(sm.p), n: dayMeals(id).length, burn: dayBurn(id), over: sm.kcal > plan + dayBurn(id) + 0.5 });
  }
  const logged = days.filter((d) => d.n);
  const avg = logged.length ? Math.round(logged.reduce((a, d) => a + d.kcal, 0) / logged.length) : 0;
  // wykres: 7 słupków względem planu (zielony w planie, terakota ponad), linia planu
  const W = 320, H = 150, padL = 8, padR = 8, padT = 18, padB = 24;
  const top = Math.max(plan * 1.25, ...days.map((d) => d.kcal)) || 1;
  const Y = (v) => padT + (1 - Math.min(1, v / top)) * (H - padT - padB);
  const slot = (W - padL - padR) / 7;
  const barW = Math.min(34, slot - 10);
  const names = state.lang === "uk" ? ["нд", "пн", "вт", "ср", "чт", "пт", "сб"] : state.lang === "en" ? ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"] : ["nd", "pn", "wt", "śr", "cz", "pt", "so"];
  const chart = `<svg class="dchart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${attr(L("Kalorie w ostatnich 7 dniach", "Калорії за 7 днів", "Calories over the last 7 days"))}">
    <line x1="${padL}" x2="${W - padR}" y1="${Y(plan).toFixed(1)}" y2="${Y(plan).toFixed(1)}" class="plan"/>
    <text x="${W - padR}" y="${(Y(plan) - 5).toFixed(1)}" class="ax" text-anchor="end">${L("plan", "план", "plan")} ${plan}</text>
    ${days.map((d, i) => {
      const x = padL + slot * i + (slot - barW) / 2;
      const y = d.kcal ? Y(d.kcal) : H - padB - 3;
      const h = Math.max(3, H - padB - y);
      const wd = new Date(d.id + "T12:00:00").getDay();
      return `<rect x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${barW.toFixed(1)}" height="${h.toFixed(1)}" rx="7" class="dbar ${d.over ? "over" : ""} ${d.n ? "" : "none"} ${d.id === diaryOpen ? "on" : ""}" data-d="${d.id}"><title>${d.id}: ${d.kcal} kcal</title></rect>
        ${d.kcal ? `<text x="${(x + barW / 2).toFixed(1)}" y="${(y - 5).toFixed(1)}" class="ax val" text-anchor="middle">${d.kcal}</text>` : ""}
        <text x="${(x + barW / 2).toFixed(1)}" y="${H - 7}" class="ax ${d.id === today ? "today" : ""}" text-anchor="middle">${names[wd]}</text>`;
    }).join("")}
  </svg>`;
  const thumbsOf = (id) => newestMeals(dayMeals(id)).slice(0, 6).map((m) => m.thumb ? `<img class="dthumb" src="${attr(m.thumb)}" alt="" onerror="this.style.visibility='hidden'">` : `<span class="dthumb ph">${icon("plate")}</span>`).join("");
  app.insertAdjacentHTML("beforeend", `
    <div class="screen">
      <div class="brand-row">
        <h1>${t("hist")}</h1>
        ${streakBadge()}
      </div>
      <div class="card">
        <div class="between"><span class="muted">${L("Ostatnie 7 dni", "Останні 7 днів", "Last 7 days")}</span><b>${avg ? `${L("średnio", "у середньому", "avg.")} ${avg} kcal` : "—"}</b></div>
        ${chart}
        <div class="legend"><span><i class="good"></i>${L("w planie", "у плані", "within plan")}</span><span><i class="over"></i>${L("ponad plan", "понад план", "over plan")}</span></div>
      </div>
      ${days.slice().reverse().map((d) => {
        const open = d.id === diaryOpen;
        const work = dayWork(d.id);
        return `<div class="card diary-day ${open ? "open" : ""} ${d.n ? "" : "empty-day"}">
          <button type="button" class="diary-head" data-open="${d.id}" aria-expanded="${open}">
            <span class="dh-copy"><b>${d.id === today ? L("Dziś", "Сьогодні", "Today") : d.id === shiftDay(today, -1) ? L("Wczoraj", "Вчора", "Yesterday") : dayLabel(d.id)}</b><small>${d.n ? `${d.n} ${d.n === 1 ? L("posiłek", "страва", "meal") : L("posiłki", "страви", "meals")} · ${L("białko", "білок", "protein")} ${d.p} g${d.burn ? ` · ${L("ruch", "рух", "move")} +${Math.round(d.burn)}` : ""}` : L("Nic nie zapisano", "Нічого не записано", "Nothing logged")}</small></span>
            <b class="dh-kcal ${d.over ? "over" : ""}">${d.n ? d.kcal : "—"}</b>${icon("chevR")}
          </button>
          ${d.n && !open ? `<div class="dthumbs">${thumbsOf(d.id)}</div>` : ""}
          ${open ? `<div class="list">${d.n ? newestMeals(dayMeals(d.id)).map(mealRow).join("") : `<p class="muted" style="padding:6px 0 10px">${L("Brak posiłków tego dnia.", "Страв цього дня немає.", "No meals that day.")}</p>`}</div>
            ${work.length ? `<div class="dwork">${work.map((w) => `<span>${icon("bolt")}${esc(w.name)}${w.amount ? ` · ${w.amount} ${w.unit === "km" ? "km" : "min"}` : ""} · +${Math.round(w.kcal)}</span>`).join("")}</div>` : ""}
            ${stepsOf(d.id) != null ? `<div class="dwork"><span>${icon("steps")}${stepsOf(d.id).toLocaleString(state.lang === "en" ? "en-GB" : "pl-PL")} ${L("kroków", "кроків", "steps")}${stepsKcal(d.id) ? ` · +${stepsKcal(d.id)}` : ""}</span></div>` : ""}` : ""}
        </div>`;
      }).join("")}
      <div class="tip"><small>${icon("sparkles")}${t("eveTip")}</small>${esc(eveningTip())}</div>
    </div>`);
  bindMeals();
  app.querySelectorAll("[data-open]").forEach((b) => {
    b.onclick = () => { diaryOpen = diaryOpen === b.dataset.open ? "" : b.dataset.open; render(); };
  });
  app.querySelectorAll(".dchart .dbar").forEach((r) => {
    r.onclick = () => { diaryOpen = r.dataset.d; render(); const el = app.querySelector(".diary-day.open"); if (el) el.scrollIntoView({ behavior: "smooth", block: "center" }); };
  });
}

function eveningTip() {
  const s = sums(iso(new Date()));
  const p = state.user.plan;
  return L(
    `Dziś ${Math.round(s.kcal)} z ${p.kcal} kcal. Białko ${Math.round(s.p)}/${p.p} g. Jutro trzymaj białko na śniadaniu — łatwiej nie dobijać węglami wieczorem.`,
    `Сьогодні ${Math.round(s.kcal)} з ${p.kcal} ккал. Білок ${Math.round(s.p)}/${p.p} г. Завтра тримай білок на сніданок — так легше не добирати вуглеводами ввечері.`,
    `Today ${Math.round(s.kcal)} of ${p.kcal} kcal. Protein ${Math.round(s.p)}/${p.p} g. Tomorrow keep protein at breakfast — easier not to catch up on carbs at night.`
  );
}

