function foldEx(s) {
  return (s || "").toLowerCase()
    .replaceAll("ą", "a").replaceAll("ć", "c").replaceAll("ę", "e").replaceAll("ł", "l")
    .replaceAll("ń", "n").replaceAll("ó", "o").replaceAll("ś", "s").replaceAll("ź", "z").replaceAll("ż", "z")
    .replaceAll("і", "i").replaceAll("ї", "i").replaceAll("є", "e").replaceAll("ґ", "g");
}
function exName(e) { return state.lang === "uk" ? e.uk : state.lang === "en" ? (e.en || e.pl) : e.pl; }
function matchEx(q) {
  const n = foldEx(q);
  if (!n) return EXERCISES.slice(0, 8);
  return EXERCISES.filter((e) => {
    const a = foldEx(e.pl), b = foldEx(e.uk), c = foldEx(e.en || "");
    return [a, b, c].some((x) => x.startsWith(n) || x.split(" ").some((w) => w.startsWith(n)));
  }).slice(0, 8);
}

