function weeklyFallback(start) {
  const goal = (state.user && state.user.goal) || "keep";
  const pool = isTeen() ? TEEN_WEEKLY : goal === "lose" ? ["kcalDays", "proteinDays", "logDays", "vegDays", "workouts", "noSnackDays"]
    : goal === "gain" ? ["kcalDays", "proteinDays", "workouts", "logDays"] : ["logDays", "proteinDays", "vegDays", "workouts"];
  const id = pool[Math.floor(dayIndex(start) / 7) % pool.length];
  return { start, id, target: WEEKLY[id].target, auto: true };
}
// wyzwanie tygodnia z postępem (poniedziałek–dziś)
function weekInfo(day) {
  day = day || iso(new Date());
  const start = weekStart(day);
  const q = questsState();
  if (!q.week || q.week.start !== start) {
    const c = state.coach && state.coach.week;
    q.week = c && c.start === start && c.weekly && WEEKLY[c.weekly.id] && (!isTeen() || TEEN_WEEKLY.includes(c.weekly.id))
      ? { start, id: c.weekly.id, target: Math.max(2, Math.min(7, Math.round(+c.weekly.target) || WEEKLY[c.weekly.id].target)) }
      : weeklyFallback(start);
  }
  const w = q.week;
  const today = iso(new Date());
  let n = 0;
  for (let i = 0; i < 7; i++) {
    const d = shiftDay(start, i);
    if (d > today) break;
    if (w.id === "kcalDays") n += questState("kcal", d).done ? 1 : 0;
    else if (w.id === "proteinDays") n += questState("protein", d).done ? 1 : 0;
    else if (w.id === "logDays") n += dayMeals(d).length >= 2 ? 1 : 0;
    else if (w.id === "workouts") n += dayWork(d).length;
    else if (w.id === "weigh2") n += weighedBetween(d, d) ? 1 : 0;
    else if (w.id === "vegDays") n += questState("veg", d).done ? 1 : 0;
    else if (w.id === "noSnackDays") n += questState("nosnack", d).done ? 1 : 0;
  }
  const def = WEEKLY[w.id] || WEEKLY.logDays;
  return { start, id: w.id, target: w.target, n: Math.min(n, w.target), done: n >= w.target, name: L(def.name[0], def.name[1], def.name[2]), auto: !!w.auto };
}
// --- aktualizacja z GitHuba (Android spoza sklepu): karta na starcie, pobranie z postępem, instalator ---
let updateInfo = null;
let updatePct = null;
window.onUpdate = (json) => {
  try { updateInfo = JSON.parse(json); } catch (_) { updateInfo = null; }
  if (updateInfo && localStorage.getItem("mealquo_update_skip") === updateInfo.version) updateInfo = null;
  if (updateInfo && state.screen === "profile") state.screen = "home";   // ręczne sprawdzenie z profilu: karta jest na Starcie
  if (updateInfo && state.screen === "home") render();
};
window.onUpdateProgress = (pct) => {
  updatePct = pct;
  if (pct === -1) { updatePct = null; toast(L("Nie udało się pobrać aktualizacji.", "Не вдалося завантажити оновлення.", "Couldn't download the update."), 3000); }
  if (pct === -2) { updatePct = null; toast(L("Zezwól Mealquo na instalowanie aktualizacji i wróć tutaj.", "Дозволь Mealquo встановлювати оновлення і повернись сюди.", "Allow Mealquo to install updates, then come back."), 4500); }
  const bar = app.querySelector("#updbar span");
  const lbl = app.querySelector("#updlbl");
  if (bar && pct >= 0) bar.style.width = Math.max(4, pct) + "%";
  if (lbl && pct >= 0) lbl.textContent = pct >= 100 ? L("Otwieram instalator…", "Відкриваю інсталятор…", "Opening the installer…") : `${pct}%`;
  if (!bar && state.screen === "home") render();
};
function updateCard() {
  if (!updateInfo) return "";
  const mb = updateInfo.size ? ` · ${(updateInfo.size / 1048576).toFixed(0)} MB` : "";
  return `<div class="card update-card">
    <span class="upd-ico">${icon("download")}</span>
    <div class="upd-copy"><b>${L(`Jest nowa wersja ${updateInfo.version}`, `Є нова версія ${updateInfo.version}`, `Version ${updateInfo.version} is out`)}</b>
      ${updatePct != null ? `<div class="near-bar" id="updbar"><span style="width:${Math.max(4, updatePct)}%"></span></div><small class="muted" id="updlbl">${updatePct}%</small>` : `<small class="muted">${L("Pobranie i instalacja zajmą chwilę, dane zostają", "Завантаження і встановлення займуть хвилину, дані лишаються", "Download and install take a moment, your data stays")}${mb}.</small>`}
    </div>
    ${updatePct == null ? `<div class="upd-actions"><button type="button" class="soft" id="updgo">${L("Zaktualizuj", "Оновити", "Update")}</button><button type="button" class="ghost small" id="updskip">${L("Później", "Пізніше", "Later")}</button></div>` : ""}
  </div>`;
}
function bindUpdate() {
  const go = app.querySelector("#updgo");
  if (go) go.onclick = () => { updatePct = 0; render(); try { MealquoNative.downloadUpdate(updateInfo.url); } catch (_) { updatePct = null; } };
  const skip = app.querySelector("#updskip");
  if (skip) skip.onclick = () => { try { localStorage.setItem("mealquo_update_skip", updateInfo.version); } catch (_) {} updateInfo = null; render(); };
}
if (window.MealquoNative && MealquoNative.updatesOn && MealquoNative.checkUpdate) {
  setTimeout(() => { try { if (MealquoNative.updatesOn()) MealquoNative.checkUpdate(); } catch (_) {} }, 4000);
  // po cichej aktualizacji (instalacja w tle) krótka informacja o nowej wersji
  try {
    const ver = MealquoNative.appVersion();
    const was = localStorage.getItem("mealquo_ver");
    if (was && was !== ver) setTimeout(() => toast(L(`Zaktualizowano do wersji ${ver}`, `Оновлено до версії ${ver}`, `Updated to version ${ver}`), 3500), 1800);
    localStorage.setItem("mealquo_ver", ver);
  } catch (_) {}
  // Android trzyma aplikację w tle: sprawdzenie także po powrocie (limit 6 h pilnuje Updater.java)
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") { try { if (MealquoNative.updatesOn()) MealquoNative.checkUpdate(); } catch (_) {} }
  });
}
window.onUpdateNone = (failed) => {
  toast(failed ? L("Nie udało się sprawdzić. Sprawdź internet.", "Не вдалося перевірити. Перевір інтернет.", "Couldn't check. Check the internet.")
    : L("Masz najnowszą wersję.", "У тебе найновіша версія.", "You have the latest version."), 2500);
};
let xpQueue = [];
let xpTimer = 0;
function xpToast(text) {
  xpQueue.push(text);
  if (xpTimer) return;
  const next = () => {
    const t = xpQueue.shift();
    if (!t) { xpTimer = 0; return; }
    toast(t, 1600);
    xpTimer = setTimeout(next, 1300);
  };
  xpTimer = setTimeout(next, 700);
}
// pełnoekranowe świętowanie (odznaka, poziom, wyzwanie); kolejka, jedno naraz
let cheerQueue = [];
function cheer(icon, title, text) {
  cheerQueue.push({ icon, title, text });
  if (!document.querySelector(".cheer")) showCheer();
}
function showCheer() {
  const c = cheerQueue.shift();
  if (!c) return;
  const box = document.createElement("div");
  box.className = "cheer";
  box.innerHTML = `<div class="cheer-card"><div class="cheer-ico">${c.icon}</div><b>${esc(c.title)}</b><p>${esc(c.text || "")}</p><button type="button" class="primary">${L("Super", "Супер", "Nice")}</button></div>`;
  document.body.appendChild(box);
  const close = () => { box.remove(); setTimeout(showCheer, 250); };
  box.onclick = close;
  setTimeout(() => { if (box.parentNode) close(); }, 9000);
}
function award(key, xp, label) {
  const q = questsState();
  if (q.awarded[key]) return false;
  q.awarded[key] = 1;
  state.points = (state.points || 0) + xp;
  if (label) xpToast(`+${xp} XP · ${label}`);
  return true;
}
function badgeDefs() {
  const meals = state.meals || [];
  const streak = streakCount();
  const prog = goalProgress();
  const moved = prog ? (prog.dir === "lose" ? prog.start - prog.now : prog.now - prog.start) : 0;   // tylko w stronę celu
  const weeks = Object.keys((state.quests && state.quests.awarded) || {}).filter((k) => k.indexOf("week:") === 0).length;
  const level = levelInfo(state.points || 0).level;
  return [
    { id: "first", icon: "plate", color: "#2e6b58", name: L("Pierwszy talerz", "Перша тарілка", "First plate"), ok: meals.length >= 1 },
    { id: "photo", icon: "camera", color: "#2f8f88", name: L("Pierwsze zdjęcie", "Перше фото", "First photo"), ok: meals.some((m) => m.thumb || m.photoId) },
    { id: "streak3", icon: "flame", color: "#e08a3c", name: L("3 dni z rzędu", "3 дні поспіль", "3 days in a row"), ok: streak >= 3 },
    { id: "streak7", icon: "flame", color: "#d8603d", name: L("Tydzień serii", "Тиждень поспіль", "A week straight"), ok: streak >= 7 },
    { id: "streak14", icon: "flame", color: "#c1452a", name: L("Dwa tygodnie serii", "Два тижні поспіль", "Two weeks straight"), ok: streak >= 14 },
    { id: "streak30", icon: "trophy", color: "#d9a520", name: L("Miesiąc serii", "Місяць поспіль", "A month straight"), ok: streak >= 30 },
    { id: "weigh1", icon: "scale", color: "#4c7fb5", name: L("Pierwsze ważenie", "Перше зважування", "First weigh-in"), ok: weightsList().length >= 1 },
    { id: "kg1", icon: "feather", color: "#7a9d6a", name: L("Pierwszy kilogram", "Перший кілограм", "First kilo"), ok: !!prog && moved >= 1 },
    { id: "kg3", icon: "feather", color: "#5e8f5a", name: L("3 kg na liczniku", "3 кг на рахунку", "3 kg on the clock"), ok: !!prog && moved >= 3 },
    { id: "kg5", icon: "gem", color: "#3e7dbf", name: L("5 kg na liczniku", "5 кг на рахунку", "5 kg on the clock"), ok: !!prog && moved >= 5 },
    { id: "kg10", icon: "gem", color: "#6c4fb0", name: L("10 kg na liczniku", "10 кг на рахунку", "10 kg on the clock"), ok: !!prog && moved >= 10 },
    { id: "half", icon: "mountain", color: "#8a6aa8", name: L("Połowa drogi", "Половина шляху", "Halfway"), ok: !!prog && prog.pct >= 50 },
    { id: "goal", icon: "flag", color: "#d9a520", name: L("Cel osiągnięty", "Ціль досягнуто", "Goal reached"), ok: !!prog && prog.pct >= 100 },
    { id: "move10", icon: "bolt", color: "#2f8f88", name: L("10 treningów", "10 тренувань", "10 workouts"), ok: (state.workouts || []).length >= 10 },
    { id: "meals50", icon: "book", color: "#b5742d", name: L("50 posiłków", "50 страв", "50 meals"), ok: meals.length >= 50 },
    { id: "meals200", icon: "book", color: "#8c5a2b", name: L("200 posiłków", "200 страв", "200 meals"), ok: meals.length >= 200 },
    { id: "week1", icon: "medal", color: "#d9a520", name: L("Wyzwanie tygodnia", "Виклик тижня", "Weekly challenge"), ok: weeks >= 1 },
    { id: "week4", icon: "medal", color: "#b8860b", name: L("4 wyzwania tygodnia", "4 виклики тижня", "4 weekly challenges"), ok: weeks >= 4 },
    { id: "level5", icon: "star", color: "#e3a72f", name: L("Poziom 5", "Рівень 5", "Level 5"), ok: level >= 5 },
    { id: "level10", icon: "star", color: "#c9a227", name: L("Poziom 10", "Рівень 10", "Level 10"), ok: level >= 10 },
  ];
}
// postęp wagi od startu celu: { start, now, target, pct, left, dir }
function goalProgress() {
  const u = state.user;
  if (!u || !u.targetWeight || u.goal === "keep") return null;
  const target = +u.targetWeight;
  if (!state.goalStart && u.plan && u.plan.from) state.goalStart = { kg: u.plan.from, day: iso(new Date()), target };
  const gs = state.goalStart;
  if (!gs) return null;
  const last = lastWeight();
  const now = last ? +last.kg : +u.weight || gs.kg;
  const total = gs.kg - target;
  if (!total) return null;
  const pct = Math.max(0, Math.min(100, Math.round(((gs.kg - now) / total) * 100)));
  const left = Math.round(Math.abs(now - target) * 10) / 10;
  return { start: gs.kg, now, target, pct, left, dir: total > 0 ? "lose" : "gain", day: gs.day };
}
// kamienie milowe: od trenera (gdy pasują do celu), inaczej równe kroki co ok. 2,5 kg
function milestones() {
  const prog = goalProgress();
  if (!prog) return [];
  const c = state.coach && state.coach.goal;
  let list = c && c.key === goalKey(prog.start, prog.target) && Array.isArray(c.milestones) && c.milestones.length
    ? c.milestones.map((m) => ({ kg: Math.round(+m.kg * 10) / 10, label: String(m.label || "").slice(0, 60) })).filter((m) => m.kg) : [];
  if (!list.length) {
    const gap = prog.target - prog.start;
    const n = Math.max(2, Math.min(4, Math.round(Math.abs(gap) / 2.5)));
    list = Array.from({ length: n }, (_, i) => ({ kg: Math.round((prog.start + gap * (i + 1) / n) * 10) / 10, label: i === n - 1 ? L("Cel", "Ціль", "Goal") : L("Kamień milowy", "Етап", "Milestone") + " " + (i + 1) }));
  }
  return list.map((m) => ({ ...m, done: prog.dir === "lose" ? prog.now <= m.kg : prog.now >= m.kg }));
}
function goalKey(from, target) { return `${Math.round(from * 10) / 10}-${Math.round(target * 10) / 10}`; }
// nowy cel zapisany w goalEdit: start postępu, pierwsze ważenie, misje na dziś od nowa
function startGoal(plan) {
  const today = iso(new Date());
  state.goalStart = { kg: plan.from, day: today, target: plan.target };
  if (!weighedBetween(today, today)) addWeight(plan.from, true);
  const q = questsState();
  delete q.days[today];
  q.week = null;
}
// zapis ważenia; przelicza plan kalorii do aktualnej wagi (cel zostaje)
function addWeight(kg, quiet) {
  kg = Math.round(+kg * 10) / 10;
  if (!kg || kg < 30 || kg > 300) return false;
  const today = iso(new Date());
  const ws = weightsList().filter((w) => w.d !== today);
  ws.push({ d: today, kg });
  ws.sort((a, b) => (a.d < b.d ? -1 : 1));
  state.weights = ws.slice(-400);
  if (state.user) {
    state.user.weight = kg;
    if (state.user.targetWeight && state.user.goal !== "keep") state.user.plan = goalPlan(state.user);
    if (!state.goalStart && state.user.targetWeight) state.goalStart = { kg, day: today, target: state.user.targetWeight };
  }
  if (!quiet) toast(L(`Zapisane: ${String(kg).replace(".", ",")} kg`, `Збережено: ${String(kg).replace(".", ",")} кг`, `Saved: ${kg} kg`));
  return true;
}
// ratunek serii: pusty wczorajszy dzień po serii ≥ 3 dni zużywa jeden ratunek
function rescueStreak() {
  const g = gameState();
  if (!g.freezes) return;
  const today = iso(new Date());
  const yest = shiftDay(today, -1);
  const logged = new Set((state.meals || []).map((m) => m.date).concat(g.frozen));
  if (logged.has(yest) || !logged.has(shiftDay(today, -2))) return;
  let n = 0;
  for (let d = shiftDay(today, -2); logged.has(d) && n < 400; d = shiftDay(d, -1)) n++;
  if (n < 3) return;
  g.freezes--;
  g.frozen = g.frozen.concat(yest).slice(-60);
  xpToast(L("Ratunek serii użyty. Seria trwa.", "Порятунок серії використано. Серія триває.", "Streak rescue used. The streak lives."));
}
// przy każdym rysowaniu startu: misje dziś i wczoraj, wyzwanie tygodnia, poziom, odznaki
// do 15.4 poziom = punkty / 50; nowe progi są wyższe, więc raz (flaga w state.game, synchronizowana) dokładamy XP do starego poziomu
function levelFix() {
  const g = gameState();
  if (g.lvlFix) return;
  const pts = state.points || 0;
  const oldLevel = Math.floor(pts / 50) + 1;
  const need = 20 * (oldLevel - 1) * (oldLevel + 2);
  g.lvlFix = { at: Date.now(), from: pts, to: Math.max(pts, need) };
  if (pts < need) state.points = need;
}
// nastolatek nie ma celu wagi: plan bez deficytu, bez postępu do celu
function teenGuard() {
  const u = state.user;
  if (!u || !isTeen(u)) return;
  if (u.goal !== "keep" || u.targetWeight || (u.plan && u.plan.goal && u.plan.goal !== "keep")) {
    u.goal = "keep";
    u.targetWeight = null;
    u.plan = calcPlan(u);
    state.goalStart = null;
  }
}
function gameTick() {
  if (!state.user) return;
  teenGuard();
  const before = JSON.stringify([state.points, state.quests, state.badges, state.game]);
  const today = iso(new Date());
  const q = questsState();
  levelFix();
  const lvlBefore = levelInfo(state.points || 0).level;
  rescueStreak();
  for (const day of [shiftDay(today, -1), today]) {
    if (dayMeals(day).length) award("first:" + day, 5, L("Dzień zapisany", "День записано", "Day logged"));
    for (const id of dayQuests(day)) {
      if (questState(id, day).done) award(`${day}:${id}`, QUESTS[id].xp, L(QUESTS[id].name[0], QUESTS[id].name[1], QUESTS[id].name[2]) + (day !== today ? L(" (wczoraj)", " (вчора)", " (yesterday)") : ""));
    }
  }
  const w = weekInfo(today);
  if (w.done && award("week:" + w.start, WEEKLY_XP, L("Wyzwanie tygodnia", "Виклик тижня", "Weekly challenge"))) {
    const g = gameState();
    g.freezes = Math.min(3, g.freezes + 1);
    cheer(badgeArt("medal", "#d9a520", true), L("Wyzwanie tygodnia zrobione", "Виклик тижня виконано", "Weekly challenge done"), L(`${w.name}: ${w.target}. +${WEEKLY_XP} XP i ratunek serii na zapas.`, `${w.name}: ${w.target}. +${WEEKLY_XP} XP і порятунок серії в запас.`, `${w.name}: ${w.target}. +${WEEKLY_XP} XP and a streak rescue in reserve.`));
  }
  const lvl = levelInfo(state.points || 0);
  if (lvl.level > lvlBefore) cheer(badgeArt("star", "#e3a72f", true), L(`Poziom ${lvl.level}`, `Рівень ${lvl.level}`, `Level ${lvl.level}`), lvl.name);
  state.badges = state.badges && typeof state.badges === "object" ? state.badges : {};
  const fresh = Object.keys(state.badges).length === 0 && (state.meals || []).length > 3;   // start gry u kogoś z historią: bez fanfar za stare odznaki
  for (const b of badgeDefs()) {
    if (!b.ok || state.badges[b.id]) continue;
    state.badges[b.id] = today;
    if (!fresh) cheer(badgeArt(b.icon, b.color, true), L("Nowa odznaka", "Нова відзнака", "New badge"), b.name);
  }
  // porządki: misje i nagrody starsze niż 3 tygodnie
  const keep = shiftDay(today, -21);
  Object.keys(q.days).forEach((d) => { if (d < keep) delete q.days[d]; });
  Object.keys(q.awarded).forEach((k) => { const d = k.split(":").pop(); if (/^\d{4}-\d{2}-\d{2}$/.test(d) && d < keep && k.indexOf("week:") !== 0) delete q.awarded[k]; });
  if (JSON.stringify([state.points, state.quests, state.badges, state.game]) !== before) save();
  coachWeek();
  coachDay();
}
function missionRow(day) {
  const ids = dayQuests(day);
  return `<div class="missions">${ids.map((id) => {
    const st = questState(id, day);
    const cls = st.done ? "done" : st.pending ? "pending" : "";
    return `<button type="button" class="mission ${cls}" data-go="journey"><span class="m-ico">${questIcon(id)}</span><b>${L(QUESTS[id].name[0], QUESTS[id].name[1], QUESTS[id].name[2])}</b><small>${st.done ? "✓ +" + QUESTS[id].xp + " XP" : esc(st.text)}</small></button>`;
  }).join("")}</div>`;
}
// prośba o ważenie raz na tydzień (cel: schudnąć / przytyć), do odłożenia na dziś
function weighCard() {
  const u = state.user;
  if (!u || isTeen(u) || u.goal === "keep" || !u.targetWeight || selectedDay !== iso(new Date())) return "";
  const today = iso(new Date());
  if (gameState().weighAsk === today || weighedBetween(shiftDay(today, -6), today)) return "";
  const last = lastWeight();
  return `<div class="card weigh-card">
    <div><b class="with-ic">${icon("scale")}${L("Czas na ważenie", "Час зважитись", "Time to weigh in")}</b><p class="muted">${last ? L(`Ostatnio ${String(last.kg).replace(".", ",")} kg (${last.d}).`, `Останнє ${String(last.kg).replace(".", ",")} кг (${last.d}).`, `Last ${last.kg} kg (${last.d}).`) : L("Najlepiej rano, przed jedzeniem.", "Найкраще вранці, до їжі.", "Best in the morning, before eating.")}</p></div>
    <div class="weigh-row"><input id="weighkg" type="number" inputmode="decimal" step="0.1" min="30" max="300" value="${last ? last.kg : Math.round(+u.weight || 70)}"><button type="button" class="soft" id="weighsave">${L("Zapisz", "Зберегти", "Save")}</button><button type="button" class="ghost small" id="weighlater">${L("Nie dziś", "Не сьогодні", "Not today")}</button></div>
  </div>`;
}
function bindGame() {
  app.querySelectorAll("[data-go]").forEach((b) => { b.onclick = () => { state.screen = b.dataset.go; render(); }; });
  const saveBtn = app.querySelector("#weighsave");
  if (saveBtn) saveBtn.onclick = () => {
    const v = parseFloat(String(app.querySelector("#weighkg").value).replace(",", "."));
    if (!addWeight(v)) { toast(L("Podaj wagę od 30 do 300 kg.", "Вкажи вагу від 30 до 300 кг.", "Enter a weight from 30 to 300 kg.")); return; }
    render();
  };
  const later = app.querySelector("#weighlater");
  if (later) later.onclick = () => { gameState().weighAsk = iso(new Date()); render(); };
}
function coachTip(fallback) {
  const c = state.coach && state.coach.day;
  if (c && c.day === selectedDay && c.text) return `<div class="tip coach"><small>${icon("sparkles")}${L("Trener", "Тренер", "Coach")}</small>${esc(c.text)}</div>`;
  return `<div class="tip"><small>${icon("sparkles")}${t("tip")}</small>${esc(fallback)}</div>`;
}
function journeyCard() {
  const lvl = levelInfo(state.points || 0);
  const streak = streakCount();
  return `<button type="button" class="card journey-card" id="gojourney"><span class="jc-lvl"><b>${lvl.level}</b></span><span class="jc-copy"><b>${L("Twoja droga", "Твій шлях", "Your journey")}</b><p class="muted">${esc(lvl.name)} · ${state.points || 0} XP${streak ? ` · ${L("seria", "серія", "streak")} ${streak}` : ""}</p></span><span class="chev">${icon("chevR")}</span></button>`;
}

// --- trener AI: /api/coach (Worker składa prompt z tych liczb) ---
const coachBusy = {};
function coachProfile() {
  const u = state.user || {};
  const plan = u.plan || {};
  const prog = goalProgress();
  return {
    sex: u.sex, age: yearsOld(u.dob) ?? ageFromDob(u.dob), teen: isTeen(u), height: u.height, weight: (lastWeight() || {}).kg || u.weight, target: u.targetWeight || u.weight,
    goal: u.goal, pace: u.pace, kgWeek: plan.kgWeek || 0, kcal: plan.kcal, protein: plan.p, diet: u.diet, pledge: u.pledge || {},
    startWeight: prog ? prog.start : 0, daysIn: prog && prog.day ? Math.max(0, dayIndex(iso(new Date())) - dayIndex(prog.day)) : 0,
  };
}
async function coachAsk(kind, payload) {
  if (coachBusy[kind]) return null;
  coachBusy[kind] = true;
  try {
    const r = await cloudApi("/api/coach", Object.assign({ kind, lang: state.lang || "pl" }, payload));
    if (r.status !== 200 || !r.data || !r.data.text) return null;
    const out = JSON.parse(r.data.text);
    out.engine = r.data.engine || "";
    return out;
  } catch (_) {
    return null;
  } finally {
    coachBusy[kind] = false;
  }
}
function coachOn() { return !!settings().coach && cloudSync() && !!state.user; }
function daySummary(day) {
  const s = sums(day);
  const meals = dayMeals(day);
  return {
    d: day, kcal: Math.round(s.kcal), plan: (state.user.plan || {}).kcal, p: Math.round(s.p), c: Math.round(s.c), f: Math.round(s.f), n: meals.length,
    burn: Math.round(dayBurn(day)), steps: stepsOf(day) || 0,
    meals: newestMeals(meals).slice(0, 8).map((m) => ({ t: String(m.title || "").slice(0, 60), kcal: Math.round(m.kcal || 0), p: Math.round(m.p || 0), time: m.time || "" })),
  };
}
// podsumowanie tygodnia i plan na nowy: raz na tydzień (poniedziałek albo pierwsze otwarcie), próba co 6 h
async function coachWeek(force) {
  if (!coachOn()) return;
  state.coach = state.coach && typeof state.coach === "object" ? state.coach : {};
  const today = iso(new Date());
  const start = weekStart(today);
  const c = state.coach;
  if (!force && c.week && c.week.start === start) return;
  if (!force && c.weekTry && c.weekTry.start === start && Date.now() - c.weekTry.at < 6 * 3600000) return;
  if ((state.meals || []).length < 2 && !force) return;    // bez dziennika nie ma czego podsumować
  c.weekTry = { start, at: Date.now() };
  const days = [];
  for (let i = 7; i >= 1; i--) days.push(daySummary(shiftDay(today, -i)));
  if (dayMeals(today).length) days.push(daySummary(today));
  const q = questsState();
  const prevStart = shiftDay(start, -7);
  const done = Object.keys(q.awarded).filter((k) => k >= prevStart && k.indexOf("week:") !== 0 && k.indexOf("first:") !== 0).map((k) => k.split(":")[1]);
  const prevWeek = q.week && q.week.start === prevStart ? q.week : null;
  const out = await coachAsk("week", {
    profile: coachProfile(), days: days.filter((d) => d.n), weights: weightsList().slice(-12),
    game: { streak: streakCount(), level: levelInfo(state.points || 0).level, done, lastWeekly: prevWeek ? prevWeek.id : "", lastWeeklyDone: !!q.awarded["week:" + prevStart], steps: stepsAvailable(), stepsAvg: stepsAvg(7) || 0, stepsGoal: stepGoal().n,
      stepsHit: [1, 2, 3, 4, 5, 6, 7].filter((i) => { const n = stepsOf(shiftDay(today, -i)); return n != null && n >= stepGoal().n; }).length },
  });
  if (!out || !out.review) return;
  state.coach.week = {
    start, at: Date.now(), engine: out.engine, review: String(out.review).slice(0, 600), focus: String(out.focus || "").slice(0, 300),
    weekly: out.weekly && WEEKLY[out.weekly.id] ? { id: out.weekly.id, target: Math.max(2, Math.min(7, Math.round(+out.weekly.target) || WEEKLY[out.weekly.id].target)) } : null,
    daily: Array.isArray(out.daily) ? [...new Set(out.daily.filter((id) => QUESTS[id] && id !== "weigh"))].slice(0, 3) : [],
    milestone: String(out.milestone || "").slice(0, 300), tips: (Array.isArray(out.tips) ? out.tips : []).slice(0, 3).map((x) => String(x).slice(0, 160)),
    stepsGoal: +out.stepsGoal >= STEP_MIN && +out.stepsGoal <= STEP_MAX ? Math.round(+out.stepsGoal / 500) * 500 : 0,
    stepsWhy: String(out.stepsWhy || "").slice(0, 200),
  };
  // wyzwanie i misje od trenera, jeśli w tym tygodniu nic jeszcze nie zaliczono
  const qs = questsState();
  const anyToday = Object.keys(qs.awarded).some((k) => k.indexOf(today + ":") === 0);
  if (qs.week && qs.week.start === start && qs.week.auto && state.coach.week.weekly) qs.week = { start, id: state.coach.week.weekly.id, target: state.coach.week.weekly.target };
  if (!anyToday && state.coach.week.daily.length === 3) delete qs.days[today];
  save();
  if (state.screen === "journey" || state.screen === "home") render();
}
// komentarz do dnia: po 2 posiłkach od 17:00 (albo po 3), ponownie gdy dzień mocno się zmienił, najwyżej 3 razy
async function coachDay() {
  if (!coachOn()) return;
  const today = iso(new Date());
  const meals = dayMeals(today);
  const hour = new Date().getHours();
  if (meals.length < 2 || (meals.length < 3 && hour < 17)) return;
  state.coach = state.coach && typeof state.coach === "object" ? state.coach : {};
  const s = sums(today);
  const cur = state.coach.day;
  const plan = state.user.plan || {};
  if (cur && cur.day === today) {
    const changed = Math.abs(s.kcal - (cur.kcal || 0)) > (plan.kcal || 2000) * 0.25;
    if (!changed || Date.now() - cur.at < 2 * 3600000 || (cur.tries || 1) >= 3) return;
  }
  const tries = cur && cur.day === today ? (cur.tries || 1) + 1 : 1;
  state.coach.day = Object.assign({}, cur && cur.day === today ? cur : { day: today }, { at: Date.now(), tries, kcal: Math.round(s.kcal) });
  const out = await coachAsk("day", {
    profile: coachProfile(),
    today: Object.assign(daySummary(today), { hour, pGoal: plan.p, streak: streakCount(), quests: dayQuests(today).map((id) => QUESTS[id].name[0] + (questState(id, today).done ? " ✓" : "")).join(", ") }),
  });
  if (!out || !out.text) return;
  state.coach.day = { day: today, at: Date.now(), tries, kcal: Math.round(s.kcal), text: String(out.text).slice(0, 500), engine: out.engine };
  save();
  if (state.screen === "home") render();
}
// ocena nowego celu w goalEdit; true gdy jest nowa odpowiedź do pokazania
async function coachGoal(plan, pace, pledge) {
  if (!coachOn()) return false;
  state.coach = state.coach && typeof state.coach === "object" ? state.coach : {};
  const key = goalKey(plan.from, plan.target) + "-" + pace;
  const cur = state.coach.goal;
  if (cur && cur.key === key && cur.message) return false;
  if (cur && cur.key === key && Date.now() - (cur.at || 0) < 60000) return false;
  state.coach.goal = { key, at: Date.now() };
  const prof = Object.assign(coachProfile(), { weight: plan.from, target: plan.target, goal: plan.goal, pace, kgWeek: plan.kgWeek, kcal: plan.kcal, protein: plan.p, pledge, startWeight: 0, daysIn: 0 });
  const out = await coachAsk("goal", { profile: prof, weights: weightsList().slice(-12) });
  if (!out || !out.message) return false;
  state.coach.goal = {
    key, at: Date.now(), engine: out.engine, verdict: ["ok", "fast", "slow"].includes(out.verdict) ? out.verdict : "ok",
    message: String(out.message).slice(0, 600), firstWeek: String(out.firstWeek || "").slice(0, 300),
    milestones: (Array.isArray(out.milestones) ? out.milestones : []).slice(0, 5).map((m) => ({ kg: Math.round(+m.kg * 10) / 10, label: String(m.label || "").slice(0, 60) })),
  };
  save();
  return true;
}
function coachGoalHtml(plan, pace) {
  if (!coachOn()) return "";
  const c = state.coach && state.coach.goal;
  const key = goalKey(plan.from, plan.target) + "-" + pace;
  if (!c || c.key !== key) return `<p class="muted">${L("Trener pisze…", "Тренер пише…", "Coach is writing…")}</p>`;
  if (!c.message) return Date.now() - (c.at || 0) < 60000 ? `<p class="muted">${L("Trener pisze…", "Тренер пише…", "Coach is writing…")}</p>` : "";
  const flag = c.verdict === "fast" ? L("Trener radzi łagodniej.", "Тренер радить м’якше.", "Coach suggests gentler.") : c.verdict === "slow" ? L("Można odrobinę śmielej.", "Можна трохи сміливіше.", "You could go a touch bolder.") : L("Trener: cel wygląda realnie.", "Тренер: ціль реальна.", "Coach: this looks realistic.");
  return `<b>${flag}</b><p>${esc(c.message)}</p>${c.firstWeek ? `<p class="muted">${esc(c.firstWeek)}</p>` : ""}${c.milestones && c.milestones.length ? `<p class="muted">${L("Kamienie milowe", "Етапи", "Milestones")}: ${c.milestones.map((m) => `${String(m.kg).replace(".", ",")} kg`).join(" → ")}</p>` : ""}`;
}

// --- ekran „Twoja droga” ---
function weightChart() {
  const ws = weightsList();
  if (!ws.length) return "";
  const u = state.user || {};
  const target = u.goal !== "keep" && u.targetWeight ? +u.targetWeight : null;
  const since = shiftDay(iso(new Date()), -90);
  let pts = ws.filter((w) => w.d >= since);
  if (pts.length < 2) pts = ws.slice(-8);
  const W = 320, H = 130, padL = 34, padR = 14, padT = 14, padB = 22;
  const kgs = pts.map((p) => +p.kg).concat(target ? [target] : []);
  const lo = Math.floor(Math.min(...kgs) - 0.6), hi = Math.ceil(Math.max(...kgs) + 0.6);
  const x0 = dayIndex(pts[0].d), x1 = Math.max(x0 + 1, dayIndex(pts[pts.length - 1].d));
  const X = (d) => padL + ((dayIndex(d) - x0) / (x1 - x0)) * (W - padL - padR);
  const Y = (kg) => padT + ((hi - kg) / (hi - lo)) * (H - padT - padB);
  const line = pts.map((p) => `${X(p.d).toFixed(1)},${Y(+p.kg).toFixed(1)}`).join(" ");
  const last = pts[pts.length - 1];
  const fmt = (n) => String(Math.round(n * 10) / 10).replace(".", state.lang === "en" ? "." : ",");
  const months = monthNames();
  const tick = (d) => { const x = new Date(d + "T12:00:00"); return `${x.getDate()} ${months[x.getMonth()]}`; };
  return `<svg class="wchart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${L("Wykres wagi", "Графік ваги", "Weight chart")}">
    <line x1="${padL}" x2="${W - padR}" y1="${Y(hi).toFixed(1)}" y2="${Y(hi).toFixed(1)}" class="grid"/>
    <line x1="${padL}" x2="${W - padR}" y1="${Y(lo).toFixed(1)}" y2="${Y(lo).toFixed(1)}" class="grid"/>
    <text x="${padL - 6}" y="${(Y(hi) + 4).toFixed(1)}" class="ax" text-anchor="end">${hi}</text>
    <text x="${padL - 6}" y="${(Y(lo) + 4).toFixed(1)}" class="ax" text-anchor="end">${lo}</text>
    ${target ? `<line x1="${padL}" x2="${W - padR}" y1="${Y(target).toFixed(1)}" y2="${Y(target).toFixed(1)}" class="target"/><text x="${W - padR}" y="${(Y(target) - 5).toFixed(1)}" class="ax tg" text-anchor="end">${L("cel", "ціль", "goal")} ${fmt(target)}</text>` : ""}
    ${pts.length > 1 ? `<polyline points="${line}" class="wline"/>` : ""}
    ${pts.map((p) => `<circle cx="${X(p.d).toFixed(1)}" cy="${Y(+p.kg).toFixed(1)}" r="4" class="wdot"><title>${p.d}: ${fmt(+p.kg)} kg</title></circle>`).join("")}
    <text x="${Math.min(W - padR, X(last.d)).toFixed(1)}" y="${(Y(+last.kg) - 9).toFixed(1)}" class="ax last" text-anchor="${X(last.d) > W - 50 ? "end" : "middle"}">${fmt(+last.kg)}</text>
    <text x="${padL}" y="${H - 6}" class="ax">${tick(pts[0].d)}</text>
    ${pts.length > 1 ? `<text x="${W - padR}" y="${H - 6}" class="ax" text-anchor="end">${tick(last.d)}</text>` : ""}
  </svg>`;
}
function journey() {
  gameTick();
  const today = iso(new Date());
  const lvl = levelInfo(state.points || 0);
  const g = gameState();
  const streak = streakCount();
  const prog = goalProgress();
  const u = state.user;
  const last = lastWeight();
  const fmt = (n) => String(Math.round(n * 10) / 10).replace(".", state.lang === "en" ? "." : ",");
  const w = weekInfo(today);
  const c = state.coach || {};
  const ids = dayQuests(today);
  const badges = badgeDefs();
  const have = state.badges || {};
  const ms = milestones();
  const weightBlock = () => {
    if (!prog && !last) return `<div class="card"><b>${L("Waga", "Вага", "Weight")}</b><p class="muted">${L("Ustaw cel w profilu, a tu zobaczysz drogę do niego.", "Постав ціль у профілі, а тут побачиш шлях до неї.", "Set a goal in your profile and the road to it shows up here.")}</p>${weighForm()}</div>`;
    const reached = prog && prog.pct >= 100;
    const delta = prog ? Math.round((prog.now - prog.start) * 10) / 10 : 0;
    return `<div class="card">
      <div class="between"><b>${L("Waga", "Вага", "Weight")}</b>${prog ? `<span class="muted">${L("cel", "ціль", "goal")} ${fmt(prog.target)} kg</span>` : ""}</div>
      <div class="wnow">${fmt(prog ? prog.now : +last.kg)} <small>kg</small>${prog && delta ? `<span class="wdelta ${(prog.dir === "lose" ? delta < 0 : delta > 0) ? "good" : ""}">${delta > 0 ? "+" : "−"}${fmt(Math.abs(delta))}</span>` : ""}</div>
      ${prog ? `<div class="pbar"><i style="width:${Math.max(2, prog.pct)}%"></i></div>
      <p class="muted" style="margin-top:6px">${reached ? L("Cel osiągnięty. Brawo.", "Ціль досягнуто. Браво.", "Goal reached. Well done.") : L(`${prog.pct}% drogi, zostało ${fmt(prog.left)} kg.`, `${prog.pct}% шляху, лишилось ${fmt(prog.left)} кг.`, `${prog.pct}% of the way, ${fmt(prog.left)} kg to go.`)}</p>` : ""}
      ${weightChart()}
      ${ms.length ? `<div class="miles">${ms.map((m) => `<div class="mile ${m.done ? "done" : ""}"><span>${m.done ? "✓" : "○"}</span><b>${fmt(m.kg)} kg</b><small>${esc(m.label)}</small></div>`).join("")}</div>` : ""}
      ${c.week && c.week.milestone ? `<p class="muted" style="margin-top:8px">${esc(c.week.milestone)}</p>` : ""}
      ${weighForm()}
      ${reached ? `<button type="button" class="soft wide" id="keepnow" style="margin-top:8px">${L("Przejdź na utrzymanie wagi", "Перейти на утримання ваги", "Switch to maintaining")}</button>` : ""}
    </div>`;
  };
  const weighForm = () => `<div class="weigh-row" style="margin-top:12px"><input id="weighkg" type="number" inputmode="decimal" step="0.1" min="30" max="300" value="${last ? last.kg : Math.round((u && +u.weight) || 70)}"><button type="button" class="soft" id="weighsave">${weighedBetween(today, today) ? L("Popraw dzisiejszą", "Виправити сьогоднішню", "Fix today's") : L("Zważ się", "Зважся", "Weigh in")}</button></div>`;
  const coachBlock = () => {
    if (!settings().coach) return `<div class="card coach-card"><b>${L("Trener AI", "AI-тренер", "AI coach")}</b><p class="muted">${L("Wyłączony w profilu. Misje i wyzwania dobiera wtedy aplikacja sama.", "Вимкнений у профілі. Місії та виклики тоді добирає сам застосунок.", "Turned off in your profile. The app then picks missions on its own.")}</p></div>`;
    const wk = c.week && c.week.start === w.start ? c.week : null;
    if (!wk) return `<div class="card coach-card"><b>${L("Trener AI", "AI-тренер", "AI coach")}</b><p class="muted">${coachBusy.week ? L("Trener czyta Twój tydzień…", "Тренер читає твій тиждень…", "The coach is reading your week…") : (state.meals || []).length < 2 ? L("Po pierwszych posiłkach trener napisze, jak Ci idzie i co ćwiczyć w tym tygodniu.", "Після перших страв тренер напише, як тобі йде і що тренувати цього тижня.", "After your first meals the coach will write how it's going and what to work on this week.") : L("Trener jeszcze nie odpowiedział.", "Тренер ще не відповів.", "The coach hasn't answered yet.")}</p>${!coachBusy.week && (state.meals || []).length >= 2 ? `<button type="button" class="soft" id="coachretry" style="margin-top:8px">${L("Zapytaj teraz", "Запитати зараз", "Ask now")}</button>` : ""}</div>`;
    return `<div class="card coach-card"><b>${L("Trener o Twoim tygodniu", "Тренер про твій тиждень", "Coach on your week")}</b>
      <p>${esc(wk.review)}</p>
      ${wk.focus ? `<p class="focus">${L("Fokus", "Фокус", "Focus")}: ${esc(wk.focus)}</p>` : ""}
      ${wk.tips && wk.tips.length ? `<ul class="tips">${wk.tips.map((x) => `<li>${esc(x)}</li>`).join("")}</ul>` : ""}
      ${stepsAvailable() ? `<p class="steps-goal">${icon("steps")}<span>${esc(stepGoalWhy())}</span></p>` : ""}
    </div>`;
  };
  app.insertAdjacentHTML("beforeend", `
    <div class="screen">
      <div class="brand-row"><h1>${L("Twoja droga", "Твій шлях", "Your journey")}</h1>${streakBadge()}</div>
      <div class="card level-card">
        <div class="lvl-num">${lvl.level}</div>
        <div class="lvl-copy"><b>${esc(lvl.name)}</b><div class="pbar"><i style="width:${Math.max(2, lvl.pct)}%"></i></div><p class="muted">${state.points || 0} XP · ${L("do poziomu", "до рівня", "to level")} ${lvl.level + 1}: ${lvl.left} XP</p>
        <p class="muted">${L("Seria", "Серія", "Streak")} ${streak} · ${L("ratunki serii", "порятунки серії", "streak rescues")}: ${g.freezes}</p></div>
      </div>
      ${isTeen() ? teenCard() : weightBlock()}
      ${coachBlock()}
      <div class="card">
        <div class="between"><b>${L("Wyzwanie tygodnia", "Виклик тижня", "Weekly challenge")}</b><span class="muted">+${WEEKLY_XP} XP · ${L("ratunek serii", "порятунок серії", "streak rescue")}</span></div>
        <p style="margin-top:6px">${esc(w.name)}: <b>${w.n} / ${w.target}</b>${w.done ? " ✓" : ""}</p>
        <div class="pbar"><i style="width:${Math.max(2, Math.round((w.n / w.target) * 100))}%"></i></div>
        <p class="muted" style="margin-top:6px">${L("Za ukończenie: ratunek serii, który uratuje jeden pusty dzień.", "За виконання: порятунок серії, який врятує один порожній день.", "Finish it for a streak rescue that saves one empty day.")}</p>
      </div>
      <div class="section-title">${L("Misje na dziś", "Місії на сьогодні", "Today's missions")}</div>
      <div class="card quest-list">${ids.map((id) => {
        const st = questState(id, today);
        return `<div class="quest ${st.done ? "done" : st.pending ? "pending" : ""}"><span class="m-ico">${questIcon(id)}</span><div><b>${L(QUESTS[id].name[0], QUESTS[id].name[1], QUESTS[id].name[2])}</b><p class="muted">${L(QUESTS[id].hint[0], QUESTS[id].hint[1], QUESTS[id].hint[2])}</p></div><span class="q-right"><b>${st.done ? "✓" : esc(st.text)}</b><small>${QUESTS[id].xp} XP</small></span></div>`;
      }).join("")}</div>
      <div class="section-title">${L("Odznaki", "Відзнаки", "Badges")} · ${Object.keys(have).length}/${badges.length}</div>
      <div class="badges">${badges.map((b) => `<div class="badge ${have[b.id] ? "on" : ""}" title="${attr(b.name)}">${badgeArt(b.icon, b.color)}<small>${esc(b.name)}</small></div>`).join("")}</div>
    </div>`);
  bindGame();
  bindTeen();
  const retry = app.querySelector("#coachretry");
  if (retry) retry.onclick = () => { coachWeek(true); render(); };
  const keep = app.querySelector("#keepnow");
  if (keep) keep.onclick = () => {
    const kg = last ? +last.kg : +u.weight;
    u.weight = kg; u.targetWeight = kg; u.goal = "keep";
    u.plan = goalPlan(u);
    state.goalStart = null;
    toast(L("Teraz utrzymujesz wagę.", "Тепер утримуєш вагу.", "Now you maintain."));
    render();
  };
}

// --- przypomnienia o misjach dnia: pory i teksty liczone tu, platformy (Remind.java, remind.js, Reminders.swift) tylko je wysyłają ---
const NUDGE_AT = { weigh: "08:30", breakfast: "09:30", veg: "12:30", protein: "16:30", move: "17:30", steps: "18:00" };
function missionNudges() {
  if (!state.user || settings().missions === false) return [];
  const today = iso(new Date());
  const ids = dayQuests(today);
  const plan = state.user.plan || {};
  const s = sums(today);
  const out = [];
  const name = (id) => L(QUESTS[id].name[0], QUESTS[id].name[1], QUESTS[id].name[2]);
  for (const id of ids) {
    if (!NUDGE_AT[id] || questState(id, today).done) continue;
    const texts = {
      weigh: [L("Zważ się", "Зважся", "Weigh in"), L("Rano, przed jedzeniem. Misja dnia czeka.", "Вранці, до їжі. Місія дня чекає.", "In the morning, before eating. Today's mission is waiting.")],
      breakfast: [L("Śniadanie z białkiem", "Сніданок з білком", "Protein breakfast"), L("Jajka, twaróg albo jogurt zaliczą misję dnia.", "Яйця, сир або йогурт зарахують місію дня.", "Eggs, curd or yogurt will tick off today's mission.")],
      veg: [L("Warzywa do obiadu", "Овочі до обіду", "Vegetables at lunch"), L("Dołóż warzywa albo owoc, misja dnia czeka.", "Додай овочі або фрукт, місія дня чекає.", "Add vegetables or a fruit, today's mission is waiting.")],
      protein: [L("Białko przed kolacją", "Білок перед вечерею", "Protein before dinner"), L(`Masz ${Math.round(s.p)} z ${plan.p || 0} g białka. Kolacja z białkiem domknie misję.`, `Маєш ${Math.round(s.p)} з ${plan.p || 0} г білка. Вечеря з білком закриє місію.`, `You have ${Math.round(s.p)} of ${plan.p || 0} g of protein. A protein dinner closes the mission.`)],
      move: [L("Ruch po południu", "Рух по обіді", "Afternoon move"), L("Spacer albo krótki trening zaliczy misję dnia.", "Прогулянка або коротке тренування зарахує місію дня.", "A walk or a short workout ticks off today's mission.")],
      steps: [L("Kroki", "Кроки", "Steps"), L(`Masz ${fmtSteps(stepsOf(today) || 0)} z ${fmtSteps(stepGoal().n)} kroków. Wieczorny spacer domknie misję.`, `Маєш ${fmtSteps(stepsOf(today) || 0)} з ${fmtSteps(stepGoal().n)} кроків. Вечірня прогулянка закриє місію.`, `You have ${fmtSteps(stepsOf(today) || 0)} of ${fmtSteps(stepGoal().n)} steps. An evening walk closes the mission.`)],
    }[id];
    out.push({ key: id, at: NUDGE_AT[id], title: texts[0], body: texts[1] });
  }
  out.sort((a, b) => (a.at < b.at ? -1 : 1));
  const open = ids.filter((id) => { const st = questState(id, today); return !st.done && !st.pending; });
  if (open.length) {
    const names = open.map(name).join(", ");
    const n = open.length;
    out.push({ key: "left", at: "19:00", title: L("Misje dnia", "Місії дня", "Today's missions"),
      body: n === 1 ? L(`Została Ci 1 misja: ${names}.`, `Лишилась 1 місія: ${names}.`, `1 mission left: ${names}.`) : L(`Zostały Ci ${n} misje: ${names}.`, `Лишилось ${n} місії: ${names}.`, `${n} missions left: ${names}.`) });
  }
  return out.slice(0, 6);
}

// --- tryb nastolatka: karta z informacją i zgodą rodzica (serwer: /v2/consent/*, e-mail przez Brevo, gdy skonfigurowane) ---
function teenCard() {
  const u = state.user || {};
  const c = state.consent || {};
  const sess = u.email && v2Session(u.email);
  let consent;
  if (!sess || !sess.token) {
    consent = `<p class="muted">${L("Zgoda rodzica lub opiekuna jest wymagana dla osób 13–15 lat. Zaloguj się kontem e-mail, żeby wysłać prośbę.", "Згода батьків чи опікуна потрібна для осіб 13–15 років. Увійди акаунтом e-mail, щоб надіслати запит.", "A parent's or guardian's consent is required at 13–15. Sign in with an e-mail account to send the request.")}</p>`;
  } else if (c.status === "confirmed") {
    consent = `<p class="consent-ok">✓ ${L("Zgoda rodzica potwierdzona", "Згода батьків підтверджена", "Parent consent confirmed")}${c.parentEmail ? ` (${esc(c.parentEmail)})` : ""}</p>`;
  } else if (c.status === "pending") {
    consent = `<p>${c.mail
      ? L(`Prośba o zgodę poszła na ${esc(c.parentEmail || "")}. Czekamy na kliknięcie w link.`, `Запит на згоду пішов на ${esc(c.parentEmail || "")}. Чекаємо на клік у посилання.`, `The consent request went to ${esc(c.parentEmail || "")}. Waiting for the link to be clicked.`)
      : L(`Adres rodzica zapisany: ${esc(c.parentEmail || "")}. E-mail z prośbą wyślemy, gdy tylko ruszy wysyłka; do tego czasu konto działa w trybie nastolatka.`, `Адресу батьків збережено: ${esc(c.parentEmail || "")}. Лист із запитом надішлемо, щойно запрацює розсилка; до того акаунт працює в режимі підлітка.`, `Parent's address saved: ${esc(c.parentEmail || "")}. We'll e-mail the request as soon as sending is live; until then the account runs in teen mode.`)}</p>
      <button type="button" class="ghost small" id="consentedit">${L("Zmień adres", "Змінити адресу", "Change address")}</button>`;
  } else {
    consent = `<p class="muted">${L("Dla osób 13–15 lat potrzebna jest zgoda rodzica lub opiekuna. Podaj jego e-mail, a wyślemy prośbę o potwierdzenie.", "Для осіб 13–15 років потрібна згода батьків чи опікуна. Вкажи їхню пошту, і ми надішлемо запит на підтвердження.", "At 13–15 a parent's or guardian's consent is needed. Enter their e-mail and we'll send a confirmation request.")}</p>
      <div class="weigh-row consent-row"><input id="parentmail" type="email" inputmode="email" placeholder="${L("e-mail rodzica", "пошта батьків", "parent's e-mail")}" value="${attr(c.parentEmail || u.parentEmail || "")}"><button type="button" class="soft" id="consentsend">${L("Wyślij", "Надіслати", "Send")}</button></div>
      <p class="muted" id="consentmsg" style="margin-top:6px">${c.mailer === false ? L("Wysyłka e-maili jeszcze nie działa: adres zapiszemy i wyślemy prośbę, gdy ruszy.", "Розсилка ще не працює: адресу збережемо і надішлемо запит, щойно запрацює.", "E-mail sending is not live yet: we'll save the address and send the request once it is.") : ""}</p>`;
  }
  return `<div class="card teen-card"><b>${L("Tryb nastolatka", "Режим підлітка", "Teen mode")}</b>
    <p>${L("Masz 13–15 lat, więc Mealquo nie prowadzi diety ani celu wagi. Plan kalorii to orientacyjne zapotrzebowanie na zdrowy wzrost, nie limit. Misje są o nawykach: białko, warzywa, regularne posiłki, ruch, woda zamiast słodkich napojów.", "Тобі 13–15 років, тож Mealquo не веде дієти й цілі ваги. План калорій — орієнтовна потреба для здорового росту, не ліміт. Місії про звички: білок, овочі, регулярні страви, рух, вода замість солодких напоїв.", "You're 13–15, so Mealquo runs no diet and no weight goal. The calorie plan is a rough need for healthy growth, not a limit. Missions are about habits: protein, vegetables, regular meals, movement, water instead of sugary drinks.")}</p>
    ${consent}
  </div>`;
}
let consentBusy = false;
async function consentRefresh(force) {
  const u = state.user;
  const sess = u && u.email && v2Session(u.email);
  if (!sess || !sess.token || !isTeen(u) || consentBusy) return;
  const c = state.consent;
  if (!force && c && c.at && Date.now() - c.at < 3600000) return;
  consentBusy = true;
  try {
    const r = await cloudApi("/api/v2/consent/status", {}, sess.token);
    if (r.status === 200 && r.data && r.data.status) {
      state.consent = Object.assign({}, r.data, { at: Date.now() });
      save();
      if (["profile", "journey", "goal"].includes(state.screen)) render();
    }
  } finally {
    consentBusy = false;
  }
}
function bindTeen() {
  if (!isTeen()) return;
  consentRefresh(false);
  const send = app.querySelector("#consentsend");
  if (send) send.onclick = async () => {
    const email = String(app.querySelector("#parentmail").value || "").trim().toLowerCase();
    const msg = app.querySelector("#consentmsg");
    if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) { msg.textContent = L("Podaj poprawny e-mail rodzica.", "Вкажи правильну пошту батьків.", "Enter a valid parent's e-mail."); return; }
    if (email === String(state.user.email || "").toLowerCase()) { msg.textContent = L("To Twój adres. Podaj adres rodzica.", "Це твоя адреса. Вкажи адресу батьків.", "That's your address. Enter the parent's."); return; }
    const sess = v2Session(state.user.email);
    send.disabled = true;
    msg.textContent = L("Wysyłam…", "Надсилаю…", "Sending…");
    const r = await cloudApi("/api/v2/consent/request", { parentEmail: email, lang: state.lang || "pl" }, sess && sess.token);
    send.disabled = false;
    if (r.status !== 200) { msg.textContent = L("Nie udało się wysłać. Spróbuj za chwilę.", "Не вдалося надіслати. Спробуй за хвилину.", "Couldn't send. Try again in a moment."); return; }
    state.user.parentEmail = email;
    state.consent = Object.assign({}, r.data, { at: Date.now() });
    render();
  };
  const edit = app.querySelector("#consentedit");
  if (edit) edit.onclick = () => { state.consent = { status: "none", mailer: state.consent && state.consent.mailer, parentEmail: state.consent && state.consent.parentEmail, at: Date.now() }; render(); };
}

// --- logowanie Google i Apple: serwer mówi (/v2/auth/config), które metody są skonfigurowane; przyciski tylko wtedy ---
const scriptLoads = {};
function loadScript(src) {
  return scriptLoads[src] || (scriptLoads[src] = new Promise((ok, no) => {
    const el = document.createElement("script");
    el.src = src;
    el.async = true;
    el.onload = ok;
    el.onerror = () => { delete scriptLoads[src]; no(new Error("load")); };
    document.head.appendChild(el);
  }));
}
function authCfg() {
  const c = state.authCfg;
  return c && typeof c === "object" ? c : {};
}
async function authCfgRefresh() {
  if (!cloudSync()) return;
  const c = state.authCfg;
  if (c && c.at && Date.now() - c.at < 3600000) return;
  state.authCfg = Object.assign({}, c || {}, { at: Date.now() });
  const r = await cloudApi("/api/v2/auth/config", {});
  if (r.status !== 200 || !r.data) return;
  const next = { at: Date.now(), google: !!r.data.google, apple: !!r.data.apple, googleClientId: String(r.data.googleClientId || ""), appleServicesId: String(r.data.appleServicesId || "") };
  const changed = JSON.stringify([next.google, next.apple, next.googleClientId, next.appleServicesId]) !== JSON.stringify([c && c.google, c && c.apple, c && c.googleClientId, c && c.appleServicesId]);
  state.authCfg = next;
  if (changed && state.screen === "login") render();
}
function nativeGoogle() { return !!(window.MealquoNative && MealquoNative.googleSignIn && MealquoNative.googleReady && MealquoNative.googleReady()); }
function nativeApple() { return !!(window.MealquoNative && MealquoNative.appleSignIn); }
function socialButtons(gIcon, aIcon) {
  const cfg = authCfg();
  const google = cfg.google && (nativeGoogle() || (cfg.googleClientId && cloudOk()));
  const apple = cfg.apple && (nativeApple() || (cfg.appleServicesId && cloudOk()));
  // stary wybór konta Google z telefonu (bez synchronizacji z serwerem) ukryty – decyzja właściciela;
  // Google wraca jako pełne logowanie (google), gdy serwer ma GOOGLE_CLIENT_IDS
  const oldPicker = false;
  const parts = [];
  if (apple) parts.push(`<button class="sso apple" id="apple">${aIcon}<span>${L("Zaloguj przez Apple", "Увійти через Apple", "Sign in with Apple")}</span></button>`);
  if (google && nativeGoogle()) parts.push(`<button class="sso google" id="gsignin">${gIcon}<span>${L("Kontynuuj z Google", "Продовжити з Google", "Continue with Google")}</span></button>`);
  else if (google) parts.push(`<div id="gsi" class="gsi"></div>`);
  if (oldPicker) parts.push(`<button class="sso google" id="google">${gIcon}<span>${L("Kontynuuj z Google", "Продовжити з Google", "Continue with Google")}</span></button>`);
  if (!parts.length) return "";
  return parts.join("") + `<div class="or"><span>${L("albo e-mail", "або пошта", "or email")}</span></div>`;
}
function bindSocial(err) {
  authCfgRefresh();
  const cfg = authCfg();
  const fail = (code) => err(code === "off"
    ? L("Logowanie Google nie jest jeszcze włączone w tej wersji.", "Вхід через Google ще не ввімкнено в цій версії.", "Google sign-in is not enabled in this version yet.")
    : L("Nie udało się zalogować. Spróbuj ponownie albo użyj e-maila.", "Не вдалося увійти. Спробуй ще раз або скористайся поштою.", "Couldn't sign in. Try again or use e-mail."));
  window.onGoogleToken = (idToken) => socialLogin("google", { idToken }, err);
  window.onGoogleTokenFail = fail;
  window.onAppleToken = (token, email, name) => socialLogin("apple", { identityToken: token, email: email || "", name: name || "" }, err);
  window.onAppleFail = () => fail("apple");
  const g = app.querySelector("#gsignin");
  if (g) g.onclick = () => { err(""); MealquoNative.googleSignIn(); };
  const gsi = app.querySelector("#gsi");
  if (gsi && cfg.googleClientId) {
    loadScript("https://accounts.google.com/gsi/client").then(() => {
      if (!window.google || !document.body.contains(gsi)) return;
      google.accounts.id.initialize({ client_id: cfg.googleClientId, callback: (r) => { if (r && r.credential) window.onGoogleToken(r.credential); }, ux_mode: "popup" });
      google.accounts.id.renderButton(gsi, { theme: "outline", size: "large", shape: "pill", width: Math.min(360, gsi.clientWidth || 320), text: "continue_with", locale: state.lang === "uk" ? "uk_UA" : state.lang === "en" ? "en_US" : "pl_PL" });
    }).catch(() => {});
  }
  const ap = app.querySelector("#apple");
  if (ap) ap.onclick = async () => {
    err("");
    if (nativeApple()) { MealquoNative.appleSignIn(); return; }
    try {
      await loadScript("https://appleid.cdn-apple.com/appleauth/static/jsapi/appleid/1/en_US/appleid.auth.js");
      AppleID.auth.init({ clientId: cfg.appleServicesId, scope: "name email", redirectURI: location.origin + "/", usePopup: true });
      const r = await AppleID.auth.signIn();
      const token = r && r.authorization && r.authorization.id_token;
      if (!token) return fail("apple");
      const user = r.user || {};
      window.onAppleToken(token, user.email || "", user.name ? [user.name.firstName, user.name.lastName].filter(Boolean).join(" ") : "");
    } catch (_) {
      fail("apple");
    }
  };
}
let socialBusy = false;
async function socialLogin(provider, body, err) {
  if (socialBusy) return;
  socialBusy = true;
  try {
    const r = await cloudApi("/api/v2/auth/" + provider, Object.assign({ device: v2Device() }, body));
    if (r.status === 200 && r.data && r.data.token && r.data.email) { enterSocialAccount(r.data.email, r.data.token, provider, body.name); return; }
    const why = r.status === 501 ? L("Ta metoda logowania nie jest jeszcze włączona.", "Цей спосіб входу ще не ввімкнено.", "This sign-in method is not enabled yet.")
      : r.status === 400 && r.data && r.data.error === "email" ? L("Apple nie podało adresu e-mail. Spróbuj jeszcze raz i udostępnij e-mail.", "Apple не передало пошту. Спробуй ще раз і поділися поштою.", "Apple did not share an e-mail. Try again and share your e-mail.")
      : L("Nie udało się zalogować. Spróbuj ponownie albo użyj e-maila.", "Не вдалося увійти. Спробуй ще раз або скористайся поштою.", "Couldn't sign in. Try again or use e-mail.");
    if (err) err(why); else toast(why, 3000);
  } finally {
    socialBusy = false;
  }
}
// konto z Google/Apple: bez hasła w telefonie (logowanie offline niemożliwe), sesja serwera jak po haśle
function enterSocialAccount(email, token, provider, name) {
  email = String(email).toLowerCase();
  const list = accounts().filter((a) => a.email !== email);
  const acc = { email, hash: "", provider, created: Date.now(), name: name || email.split("@")[0] };
  list.push(acc);
  saveAccounts(list);
  v2Store(email, { token, cursor: 0, synced: {} });
  enterAccount(acc, { provider }, true);
}

function unionById(a, b) {
  const map = new Map();
  (b || []).forEach((x) => { if (x && x.id != null) map.set(String(x.id), x); });
  (a || []).forEach((x) => { if (x && x.id != null) map.set(String(x.id), x); });
  return [...map.values()];
}
function finishBoot() { syncReady = true; }
window.onJournal = (packed) => {
  let blob = null;
  try { blob = JSON.parse(decodeURIComponent(escape(atob(packed)))); } catch (_) {}
  if (!blob || !blob.state) { finishBoot(); return; }
  const remote = blob.state;
  fixDates(remote);
  const remoteNewer = (blob.rev || 0) > (state.rev || 0);
  const deleted = new Set([...(state.deleted || []), ...(remote.deleted || [])].map(String));
  const meals = unionById(state.meals, remote.meals).filter((m) => !deleted.has(String(m.id)));
  const workouts = unionById(state.workouts, remote.workouts);
  applyingRemote = true;
  if (remoteNewer) {
    const screen = state.screen;
    Object.keys(state).forEach((k) => delete state[k]);
    Object.assign(state, remote);
    state.screen = screen;
    state.rev = blob.rev;
  }
  state.meals = meals;
  state.workouts = workouts;
  state.deleted = [...deleted];
  if (Array.isArray(blob.accounts)) {
    const mine = accounts();
    const known = new Set(mine.map((a) => a.email));
    blob.accounts.forEach((a) => { if (a && a.email && !known.has(a.email)) mine.push(a); });
    saveAccounts(mine);
  }
  state.syncNote = L("Dziennik z Dysku.", "Щоденник з Диска.", "Journal from Drive.");
  render();
  applyingRemote = false;
  finishBoot();
  if (!remoteNewer) schedulePush();
};
window.onSyncLinked = (mode) => {
  state.syncNote = L("Połączono z plikiem na Dysku.", "Файл на Диску підключено.", "Drive file connected.");
  finishBoot();
  if (mode === "open" && window.MealquoNative && window.MealquoNative.pullJournal) window.MealquoNative.pullJournal();
  else schedulePush();
  if (state.screen === "profile") render();
};
window.onSyncStatus = (code) => {
  if (code === "saved") state.syncNote = L("Zapisane na Dysku.", "Збережено на Диску.", "Saved to Drive.");
  if (code === "fail") state.syncNote = L("Nie udało się zapisać na Dysku.", "Не вдалося зберегти на Диск.", "Couldn’t save to Drive.");
  if (code === "off") finishBoot();
  const el = document.getElementById("syncst");
  if (el && state.syncNote) el.textContent = state.syncNote;
};
setTimeout(finishBoot, 2500);
if (window.MealquoNative && window.MealquoNative.pullJournal) window.MealquoNative.pullJournal();
if (state.user && state.user.email) pullCloud();

render();
